-- 2. 106 entradas novas
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como editar o perfil do corretor com CRECI, contatos e redes sociais$kb$, $kb$Acesse Configurações › Equipe (/app/configuracoes/equipe) e, na coluna Perfil de corretor, clique em Ver perfil público. Isso abre a tela de edição do corretor (/app/corretores/<id>). Lá você preenche Nome completo (obrigatório), Cargo / Função, E-mail, Telefone, WhatsApp, URL pública (slug), Número do CRECI, UF, Comissão padrão (%), Biografia, Instagram, Facebook, LinkedIn e Site pessoal. Se o slug ficar em branco, ele é gerado a partir do nome. Clique em Salvar alterações. O botão Ver no site abre a página pública do corretor.$kb$, $kb$backend-equipe$kb$, ARRAY[$kb$onde coloco o creci do corretor?$kb$,$kb$como editar os dados de um corretor$kb$,$kb$como mudar o whatsapp do corretor no site$kb$,$kb$onde cadastro a bio do corretor$kb$,$kb$como alterar a comissão padrão do corretor$kb$,$kb$onde edito o instagram do corretor$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como trocar a foto do corretor$kb$, $kb$Vá em Configurações › Equipe e clique em Ver perfil público ao lado do corretor para abrir a edição (/app/corretores/<id>). Na seção Foto, clique em Enviar foto (ou Trocar foto, se já houver uma) e escolha uma imagem. A imagem é comprimida automaticamente antes do envio, e a foto anterior é substituída. Para tirar a foto, clique no ícone de lixeira e confirme em Remover a foto?. Essa é a foto que aparece na página pública do corretor.$kb$, $kb$backend-equipe$kb$, ARRAY[$kb$como trocar a foto do corretor$kb$,$kb$como colocar foto no perfil do corretor$kb$,$kb$remover foto do corretor$kb$,$kb$a foto do corretor não aparece no site$kb$,$kb$onde envio a foto do corretor$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como desativar um corretor ou esconder ele do site$kb$, $kb$Abra a edição do corretor em Configurações › Equipe › Ver perfil público (/app/corretores/<id>). No fim do formulário há duas chaves: Ativo na equipe e Visível no site público. Desligue Ativo na equipe para desativar o corretor, ou desligue Visível no site público para tirar o perfil do site sem desativá-lo. Depois clique em Salvar alterações. A página pública (/corretor/<slug>) só aparece se as duas opções estiverem ligadas. Se alguma estiver desligada, o visitante vê Corretor não encontrado.$kb$, $kb$backend-equipe$kb$, ARRAY[$kb$como desativar um corretor$kb$,$kb$como tirar o corretor do site$kb$,$kb$esconder corretor da vitrine$kb$,$kb$corretor saiu da imobiliária, o que faço?$kb$,$kb$como deixar o perfil do corretor invisível$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como remover um membro da equipe$kb$, $kb$Em Configurações › Equipe (/app/configuracoes/equipe), localize a pessoa na tabela Equipe e clique no ícone de lixeira na coluna Ações. Confirme em Remover este membro da imobiliária?. A remoção tira todos os papéis da pessoa nesta imobiliária, mas não exclui a conta dela no imoB365. Você não pode remover a si mesmo, e só administradores podem gerenciar a equipe. Para manter o histórico do corretor e só tirá-lo do site, use as chaves Ativo na equipe e Visível no site público no perfil dele.$kb$, $kb$backend-equipe$kb$, ARRAY[$kb$como remover um usuário da equipe$kb$,$kb$como excluir um corretor do sistema$kb$,$kb$tirar acesso de um funcionário$kb$,$kb$como desvincular alguém da imobiliária$kb$,$kb$não consigo remover a mim mesmo$kb$,$kb$como bloquear acesso de ex-corretor$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como criar o perfil público de um corretor que ainda não tem$kb$, $kb$Em Configurações › Equipe, os membros com papel Corretor mostram na coluna Perfil de corretor o link Ver perfil público ou, se ainda não houver perfil, Criar perfil público. Clique em Criar perfil público para abrir a tela Novo corretor (/app/corretores/novo). Preencha os dados (Nome completo é obrigatório) e clique em Cadastrar corretor. Quando você adiciona um membro já com o papel Corretor, o perfil público é criado automaticamente junto. A quantidade de corretores está sujeita ao limite de usuários do plano.$kb$, $kb$backend-equipe$kb$, ARRAY[$kb$como criar perfil publico do corretor$kb$,$kb$corretor não aparece no site$kb$,$kb$como cadastrar novo corretor no site$kb$,$kb$onde fica criar perfil de corretor$kb$,$kb$como fazer a vitrine do corretor$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Quais são as permissões de cada papel (Admin, Corretor, Atendente, Jurídico, Financeiro)$kb$, $kb$Os papéis são escolhidos em Configurações › Equipe, no campo Papel. Administrador: acesso completo a Imobiliário, Jurídico, Financeiro, Marketing, Central de Atendimento e E-Learning, além de gerenciar as Configurações. Corretor: lê e edita no Imobiliário, só lê Jurídico, Marketing e E-Learning, não tem acesso ao Financeiro nem às Configurações, e no Atendimento vê apenas os chamados atribuídos a ele. Atendente: lê e edita no Imobiliário (leads e visitas), tem acesso completo à Central de Atendimento e só lê Marketing e E-Learning. Jurídico: acesso completo ao Jurídico e só leitura no Imobiliário e E-Learning. Financeiro: acesso completo ao Financeiro, só leitura no Imobiliário e E-Learning, e só atua em contratos que estejam na etapa financeira. Se a pessoa tiver mais de um papel, valem as permissões somadas, e o módulo também precisa estar incluído no plano.$kb$, $kb$backend-equipe$kb$, ARRAY[$kb$o que o corretor pode ver no sistema?$kb$,$kb$corretor tem acesso ao financeiro?$kb$,$kb$qual a diferença entre admin e corretor$kb$,$kb$quais as permissões do atendente$kb$,$kb$o que o papel jurídico acessa$kb$,$kb$por que não vejo o menu financeiro?$kb$,$kb$como funcionam os perfis de acesso$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Por que não consigo adicionar mais usuários na equipe$kb$, $kb$Em Configurações › Equipe, o quadro Usuários na conta mostra quantos membros você tem em relação ao limite do plano (por exemplo, 2 / 2). Quando o limite é atingido, o botão Adicionar fica bloqueado e aparece o aviso Cota do plano atingida, com um link para Plano & Contratação. Os limites de usuários por plano são: Free 1, Basic 2, Standard 5, Pro 15 e Business ilimitado. A pessoa convidada também precisa já ter uma conta criada em /signup, senão aparece o erro Nenhum usuário com este e-mail. Para liberar mais vagas, faça upgrade em Configurações › Plano & Contratação (/app/contratacao).$kb$, $kb$backend-equipe$kb$, ARRAY[$kb$não consigo adicionar corretor$kb$,$kb$cota de usuários atingida$kb$,$kb$quantos usuários meu plano permite$kb$,$kb$botão adicionar membro desabilitado$kb$,$kb$erro nenhum usuário com este e-mail$kb$,$kb$limite de corretores do plano$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como funciona a página pública do corretor$kb$, $kb$Cada corretor ativo e visível tem uma página pública no endereço /corretor/<slug>, que pode ser aberta pelo botão Ver no site na edição do corretor. A página mostra a foto, o CRECI com UF, o botão WhatsApp, o telefone, o e-mail, a seção Sobre (biografia), os links das redes sociais e a lista de Imóveis publicados e ativos em que ele é o corretor responsável. O visitante pode clicar em Salvar contato para baixar o cartão de contato (vCard). O slug pode ser alterado no campo URL pública (slug).$kb$, $kb$backend-equipe$kb$, ARRAY[$kb$qual o link da minha página de corretor$kb$,$kb$como divulgar meu perfil de corretor$kb$,$kb$meus imóveis não aparecem na minha página$kb$,$kb$como o cliente salva meu contato$kb$,$kb$onde vejo minha página pública$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como enviar o CIRP (carteira do CRECI)$kb$, $kb$Em Imobiliário › Cartão Virtual (/app/cartao-virtual), role até a seção CIRP (carteira do CRECI). Clique na área de envio para mandar uma foto ou um PDF da carteira, com tamanho máximo de 10MB. Depois do envio aparece a data, e você pode clicar em Substituir para trocar o arquivo ou remover o documento. O CIRP é um documento pessoal, visível só para você e para a administração da imobiliária, e nunca aparece na página pública.$kb$, $kb$backend-equipe$kb$, ARRAY[$kb$onde envio minha carteirinha do creci$kb$,$kb$como anexar o cirp$kb$,$kb$o cirp aparece no site?$kb$,$kb$tamanho máximo do arquivo do creci$kb$,$kb$como trocar o documento do creci$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como ativar a autenticação em dois fatores (MFA)$kb$, $kb$Vá em Configurações › Segurança (/app/configuracoes/seguranca), na seção Autenticação em dois fatores (MFA). Clique em Adicionar autenticador TOTP e escaneie o QR Code com um aplicativo autenticador, como Google Authenticator, 1Password ou Authy. Se preferir, digite o segredo mostrado na tela. Informe o Código de 6 dígitos e clique em Confirmar. A partir daí, a cada login a tela Entrar pede o Código de verificação. Para remover ou trocar o autenticador, clique na lixeira ao lado dele e confirme Remover este fator de autenticação?.$kb$, $kb$backend-configuracoes$kb$, ARRAY[$kb$como ativar 2fa$kb$,$kb$como ligar autenticação em dois fatores$kb$,$kb$como usar google authenticator no imob365$kb$,$kb$como desativar o mfa$kb$,$kb$troquei de celular e preciso trocar o autenticador$kb$,$kb$onde configuro a segurança da conta$kb$,$kb$pede código de 6 dígitos no login$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como redefinir a senha (esqueci minha senha)$kb$, $kb$Na tela Entrar (/login), digite seu e-mail no campo E-mail, clique em Esqueceu a senha? e depois em Enviar link de redefinição. Você recebe um e-mail com um link para a página Redefinir senha (/reset-password). Digite a Nova senha e a Confirmar senha, com no mínimo 8 caracteres, e clique em Atualizar senha. Se já estiver logado, você também pode ir em Minha conta › Perfil (/conta/perfil) e clicar em Redefinir senha para receber o link por e-mail.$kb$, $kb$backend-conta$kb$, ARRAY[$kb$esqueci minha senha$kb$,$kb$como trocar minha senha$kb$,$kb$como redefinir senha$kb$,$kb$não recebi o link de redefinição$kb$,$kb$qual o tamanho mínimo da senha$kb$,$kb$como alterar a senha estando logado$kb$]::text[], true)
