INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como entrar no imoB365 (login)$kb$, $kb$Acesse /login, preencha E-mail e Senha e clique em Entrar. Também dá para entrar via rede social, com os botões Google, Facebook, LinkedIn ou Instagram. Se o MFA estiver ativo, a tela pede o Código de verificação de 6 dígitos do seu app autenticador, e você clica em Verificar. Se ainda não tiver conta, clique em Criar conta (/signup), onde a senha precisa ter pelo menos 8 caracteres. Clientes finais (compradores e locatários) entram na área Minha conta (/conta), e imobiliárias e corretores entram no painel (/app).$kb$, $kb$backend-conta$kb$, ARRAY[$kb$como fazer login$kb$,$kb$posso entrar com google?$kb$,$kb$como criar uma conta$kb$,$kb$onde fica a tela de login$kb$,$kb$entrar com facebook ou linkedin$kb$,$kb$pede código de verificação ao entrar$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como alterar meu nome e minha foto de perfil$kb$, $kb$Vá em Minha conta › Perfil (/conta/perfil), na tela Meu perfil. Altere o Nome e clique em Salvar alterações. O e-mail não pode ser editado ali: para trocá-lo, fale com o suporte. Para contas de corretor existe a seção Sua foto, que aparece no seu site público e na home do portal: clique em Enviar foto (PNG, JPEG, SVG ou WEBP) ou em Remover. Salvar essa foto exige permissão de administrador no seu espaço.$kb$, $kb$backend-conta$kb$, ARRAY[$kb$como mudar minha foto$kb$,$kb$como trocar meu nome no perfil$kb$,$kb$como alterar meu e-mail$kb$,$kb$onde fica meu perfil$kb$,$kb$não consigo salvar minha foto$kb$,$kb$como colocar avatar$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como mudar o tema para claro ou escuro$kb$, $kb$No painel (/app), clique no botão de tema na barra superior, que tem um ícone de sol, lua ou monitor. Cada clique alterna entre Claro, Escuro e Sistema, sendo que Sistema segue a configuração do seu computador ou celular. No celular, abra o menu Mais opções e toque em Alternar tema. A preferência fica salva no seu perfil. O modo escuro vale só para as áreas internas (/app e /admin), e o site público é sempre exibido no tema claro.$kb$, $kb$backend-conta$kb$, ARRAY[$kb$como ativar modo escuro$kb$,$kb$como mudar o tema$kb$,$kb$dark mode$kb$,$kb$como voltar para o tema claro$kb$,$kb$o site público fica escuro?$kb$,$kb$tema automático do sistema$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como exportar meus dados pessoais (LGPD)$kb$, $kb$Acesse Configurações › Privacidade (LGPD) (/app/configuracoes/privacidade). Na seção Exportar meus dados, clique em Exportar JSON. É baixado o arquivo meus-dados-<id>.json com seu perfil, leads, interações e mensagens de leads, notificações e preferências de notificação. É um direito do titular previsto na Lei Geral de Proteção de Dados e pode ser usado a qualquer momento.$kb$, $kb$backend-configuracoes$kb$, ARRAY[$kb$como baixar meus dados$kb$,$kb$exportar dados lgpd$kb$,$kb$quero uma cópia dos meus dados$kb$,$kb$onde fica privacidade$kb$,$kb$direitos do titular lgpd$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como encerrar minha conta (LGPD)$kb$, $kb$Vá em Configurações › Privacidade (LGPD) (/app/configuracoes/privacidade), na seção Encerrar conta. Digite EXCLUIR no campo de confirmação e clique em Encerrar conta. Isso anonimiza o seu perfil (nome, telefone e foto), apaga suas notificações e desconecta a sessão. A exclusão definitiva dos registros precisa ser pedida ao suporte.$kb$, $kb$backend-configuracoes$kb$, ARRAY[$kb$como excluir minha conta$kb$,$kb$como apagar minha conta$kb$,$kb$quero encerrar meu cadastro$kb$,$kb$excluir dados lgpd$kb$,$kb$como cancelar minha conta definitivamente$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como configurar minhas notificações$kb$, $kb$Acesse Configurações › Notificações (/app/configuracoes/notificacoes). Ligue ou desligue cada opção: E-mail · novo lead, E-mail · visitas, E-mail · contratos, E-mail · comissões, In-app · novo lead e In-app · visitas. Todas vêm ligadas por padrão. Clique em Salvar preferências. As preferências são individuais, de cada usuário. As notificações in-app aparecem no sino da barra superior.$kb$, $kb$backend-configuracoes$kb$, ARRAY[$kb$como parar de receber e-mails de lead$kb$,$kb$configurar notificações$kb$,$kb$desligar aviso de visitas$kb$,$kb$onde ativo notificações por e-mail$kb$,$kb$como receber aviso de novo lead$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como gerar uma chave de API$kb$, $kb$Vá em Configurações › API (/app/configuracoes/api). Em Nova chave de API, digite um nome (ex.: site institucional) e clique em Gerar. A chave completa aparece uma única vez com o aviso Copie agora, não mostraremos novamente: use o botão de copiar e guarde-a. Em Chaves ativas você vê o prefixo, a data de criação e o último uso, e pode revogar a chave pela lixeira. As chamadas devem enviar o header X-Api-Key, com acesso aos endpoints GET /api/public/v1/imoveis (até 100 por página), GET /api/public/v1/imoveis/:slug e POST /api/public/v1/leads, sempre com dados só do seu tenant.$kb$, $kb$backend-configuracoes$kb$, ARRAY[$kb$como gerar api key$kb$,$kb$onde pego a chave da api$kb$,$kb$como integrar meu site com o imob365$kb$,$kb$perdi minha chave de api$kb$,$kb$como revogar chave api$kb$,$kb$quais endpoints a api tem$kb$,$kb$como criar lead pela api$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como configurar webhooks$kb$, $kb$Acesse Configurações › Webhooks (/app/configuracoes/webhooks). Em Novo webhook, informe o Nome (ex.: Zapier / N8N) e a URL, escolha os Eventos (Novo lead criado, Lead atribuído a um corretor, Lead convertido em negócio, Imóvel publicado, Contrato assinado, Contrato ativado) e clique em Adicionar. Cada entrega leva o header X-Imob365-Signature, e o Secret de cada webhook pode ser exibido pelo ícone de olho. Use a chave para pausar ou reativar um webhook e a lixeira para excluí-lo. Em Últimas entregas você acompanha o status (Entregue, Pendente, Tentando novamente, Falhou, Cancelada) e o código HTTP retornado.$kb$, $kb$backend-configuracoes$kb$, ARRAY[$kb$como configurar webhook$kb$,$kb$integrar com zapier$kb$,$kb$integrar com n8n$kb$,$kb$como receber evento de novo lead$kb$,$kb$webhook falhou$kb$,$kb$onde vejo o secret do webhook$kb$,$kb$como pausar webhook$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como usar o checklist de Go-live$kb$, $kb$Vá em Configurações › Go-live (/app/configuracoes/golive), na tela Status do Lançamento (Go-Live). A aba Checklist Geral mostra a barra de progresso e os itens: Dados da imobiliária preenchidos (CNPJ + CRECI), Plano selecionado, Site público configurado e publicado, Pelo menos 1 imóvel publicado, Pelo menos 1 corretor ativo e Páginas institucionais publicadas (opcional). Cada item tem o link Configurar ou Revisar. A aba Diagnóstico de Integrações mostra o status de E-mail Transacional, Portais Imobiliários, Google Maps & Geocoding, WhatsApp Business API, Pixels de Tracking, Assinatura Eletrônica, Cobrança e Cartórios.$kb$, $kb$backend-configuracoes$kb$, ARRAY[$kb$o que falta para lançar meu site$kb$,$kb$checklist de go live$kb$,$kb$como saber se está tudo configurado$kb$,$kb$diagnóstico de integrações$kb$,$kb$como publicar a imobiliária no ar$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como ver o plano atual e o uso da cota$kb$, $kb$Acesse Configurações › Visão geral (/app/configuracoes). No topo aparecem os cartões Plano atual, Módulos opcionais em uso, Papéis nesta conta e Uso da cota. Mais abaixo, a seção Consumo de módulos do plano lista os módulos com a descrição de cada um. Para mudar de plano, use Configurações › Plano & Contratação ou o botão Planos & Assinatura na barra superior.$kb$, $kb$backend-configuracoes$kb$, ARRAY[$kb$qual é meu plano atual$kb$,$kb$como ver uso da cota$kb$,$kb$quantos módulos estou usando$kb$,$kb$onde vejo meu plano$kb$,$kb$visão geral das configurações$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Quanto dura o teste grátis e o que acontece quando acaba$kb$, $kb$Ao concluir o onboarding, você ganha automaticamente o Trial Business por 30 dias, com todos os módulos liberados e acesso imediato. Quando os 30 dias terminam, você recebe o e-mail Seu período de teste terminou, escolha um plano e tem mais 3 dias de carência para contratar em /app/contratacao. Se não houver assinatura paga confirmada até o fim da carência, a conta passa automaticamente para o plano Free. No Free o limite é de 5 imóveis e 1 usuário.$kb$, $kb$backend-planos$kb$, ARRAY[$kb$quanto tempo dura o teste grátis$kb$,$kb$o trial é de quantos dias$kb$,$kb$o que acontece quando o teste acaba$kb$,$kb$perco meus dados depois do trial?$kb$,$kb$como continuar depois do período de teste$kb$,$kb$minha conta virou free$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Quais são os planos e os limites de imóveis e usuários$kb$, $kb$O imoB365 tem cinco planos. Free: grátis, até 5 imóveis e 1 usuário. Basic: R$ 99,90/mês, até 20 imóveis, 2 usuários e 3 módulos opcionais. Standard: R$ 199,90/mês, até 60 imóveis, 5 usuários e 5 módulos. Pro: R$ 399,90/mês, até 140 imóveis, 15 usuários e 8 módulos. Business: sob consulta, com imóveis, usuários e módulos ilimitados. Pela tabela comparativa, Marketing (portais e blog) e Jurídico (modelos) começam no Standard, e Financeiro, assinatura digital e API/Webhooks começam no Pro. Consulte os valores atualizados e o desconto do ciclo Anual em /planos.$kb$, $kb$backend-planos$kb$, ARRAY[$kb$quais os planos do imob365$kb$,$kb$quanto custa o imob365$kb$,$kb$quantos imóveis posso cadastrar$kb$,$kb$limite de usuários por plano$kb$,$kb$qual plano tem financeiro$kb$,$kb$diferença entre basic standard e pro$kb$,$kb$tem plano gratuito?$kb$,$kb$quanto custa o plano pro$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$O que fazer quando aparece Limite do plano atingido$kb$, $kb$A mensagem Limite do plano atingido (…). Faça upgrade do plano para adicionar mais. aparece quando você tenta cadastrar um imóvel ou um corretor além do limite do plano. Os limites são: Free 5 imóveis e 1 usuário, Basic 20 e 2, Standard 60 e 5, Pro 140 e 15, e Business ilimitado. Para continuar, faça upgrade em Configurações › Plano & Contratação (/app/contratacao) ou remova cadastros que não usa mais.$kb$, $kb$backend-planos$kb$, ARRAY[$kb$erro limite do plano atingido$kb$,$kb$não consigo cadastrar mais imóveis$kb$,$kb$passei do limite de imóveis$kb$,$kb$não consigo adicionar mais corretores$kb$,$kb$como aumentar o limite de imóveis$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como funciona o primeiro acesso (onboarding)$kb$, $kb$No primeiro login você é levado para /onboarding (Bem-vindo ao imob365), que tem 3 etapas. Etapa 1, Perfil: escolha Corretor (profissional autônomo com CRECI) ou Imobiliária (empresa com equipe de corretores). Etapa 2, Dados: Nome Completo e Telefone / WhatsApp; o CRECI é obrigatório para corretor, e para imobiliária são pedidos Nome da Imobiliária (obrigatório) e CNPJ (opcional), além de Cidades de atuação e Região de atuação, ambas opcionais. Etapa 3, Módulos: marque os de interesse entre Vendas & Imóveis (sempre incluído), Financeiro, Marketing & Site, Jurídico e E-Learning, e clique em Solicitar Acesso. O Trial Business de 30 dias é ativado na hora e você entra no painel. Corretores autônomos já recebem os papéis Administrador e Corretor e um perfil público.$kb$, $kb$backend-geral$kb$, ARRAY[$kb$como começar a usar o imob365$kb$,$kb$o que é o onboarding$kb$,$kb$creci é obrigatório no cadastro?$kb$,$kb$como cadastrar minha imobiliária$kb$,$kb$primeiro acesso ao sistema$kb$,$kb$preciso de cnpj para cadastrar?$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Minha conta está aguardando aprovação, o que fazer$kb$, $kb$Se aparecer a tela dizendo que a conta foi criada com sucesso e está aguardando homologação do Administrador Geral imob365, seu acesso ainda não foi liberado. A tela mostra Identificação, Perfil, Plano Pretendido e o status da Assinatura. A aprovação é feita pela equipe imoB365 na tela Aprovações Pendentes, exclusiva do super-administrador. Contas que concluem o onboarding com o Trial Business são aprovadas automaticamente. Se a espera demorar, clique em Contatar Suporte (contato@imob365.com.br) ou em Sair da minha conta.$kb$, $kb$backend-geral$kb$, ARRAY[$kb$minha conta está aguardando aprovação$kb$,$kb$quanto tempo demora a aprovação$kb$,$kb$não consigo acessar o painel$kb$,$kb$conta pendente de homologação$kb$,$kb$quem aprova meu cadastro$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como favoritar imóveis e organizar em pastas$kb$, $kb$No portal, clique no ícone de coração (Adicionar aos favoritos) do imóvel. É preciso estar logado: se não estiver, você é levado para o login. Os imóveis salvos ficam em Minha conta › Favoritos (/conta/favoritos). Em cada card dá para escolher uma pasta (Para visitar, Comparar ou Descartado) e filtrar pelos chips Todos, Sem pasta ou por pasta. Para tirar um imóvel da lista, clique no coração novamente.$kb$, $kb$backend-conta$kb$, ARRAY[$kb$como salvar imóvel nos favoritos$kb$,$kb$onde vejo meus favoritos$kb$,$kb$como organizar favoritos$kb$,$kb$como remover um favorito$kb$,$kb$favoritar sem login$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como salvar uma busca e receber alertas por e-mail$kb$, $kb$Na página de busca (/buscar), aplique os filtros e clique em Salvar busca. Na janela Salvar esta busca, dê um Nome, ligue Avisar por e-mail novos imóveis se quiser ser avisado e clique em Salvar. É preciso estar logado. As buscas ficam em Minha conta › Buscas salvas (/conta/buscas), onde você liga ou desliga os alertas, clica em Ver matches para ver imóveis compatíveis ou exclui a busca. A fila de alertas é processada a cada 15 minutos.$kb$, $kb$backend-conta$kb$, ARRAY[$kb$como salvar uma pesquisa$kb$,$kb$como receber alerta de imóvel novo$kb$,$kb$onde ficam minhas buscas salvas$kb$,$kb$desativar alerta por e-mail$kb$,$kb$como ser avisado de imóveis novos$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como conversar com o anunciante pelo chat$kb$, $kb$Na página do imóvel, clique em Conversar com o anunciante. Uma conversa é aberta em Minha conta › Conversas (/conta/chat). Todas as suas conversas ficam nessa área, acessível pelo menu lateral da Minha conta. Do lado da imobiliária, o corretor responde pelo ícone de chat na barra superior do painel (/app/chat).$kb$, $kb$backend-conta$kb$, ARRAY[$kb$como falar com o corretor$kb$,$kb$onde vejo minhas conversas$kb$,$kb$como mandar mensagem para o anunciante$kb$,$kb$onde respondo as mensagens dos clientes$kb$,$kb$chat com o cliente$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como abrir um chamado de suporte com a equipe imoB365$kb$, $kb$Acesse a página /atendimento ou clique no botão flutuante Central de Atendimento no site público. Em Abrir novo chamado, preencha Seu nome, Seu e-mail, Telefone / WhatsApp (opcional) e a mensagem em Como podemos ajudar?, e clique em Abrir chamado. Você recebe o número do chamado (ex.: CH-000123): guarde-o. Para ver a resposta, use Acompanhar chamado em /atendimento, informando o número e o e-mail usado na abertura. Se estiver logado como cliente, os chamados também ficam em Minha conta › Meus chamados (/conta/atendimento).$kb$, $kb$backend-atendimento$kb$, ARRAY[$kb$como falar com o suporte do imob365$kb$,$kb$como abrir chamado$kb$,$kb$como acompanhar meu chamado$kb$,$kb$perdi o número do chamado$kb$,$kb$onde vejo meus chamados$kb$,$kb$contato com suporte$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como responder um chamado com nota interna, resposta rápida ou sugestão da IA$kb$, $kb$Em Central de Atendimento › Chamados (/app/atendimento), abra o chamado e escreva no campo Escrever resposta. Para usar um texto pronto, escolha uma opção em Resposta rápida. Para que a IA proponha um texto, clique em Sugerir resposta (IA). Marque Nota interna (não visível ao solicitante) para registrar um comentário só para a equipe; nesse caso o botão vira Registrar nota. Ao enviar a primeira resposta não interna, o chamado com status Novo passa para Em atendimento, e o solicitante é avisado por e-mail ou WhatsApp quando esses canais estão configurados.$kb$, $kb$backend-atendimento$kb$, ARRAY[$kb$como responder um chamado$kb$,$kb$o que é nota interna$kb$,$kb$como usar resposta rápida$kb$,$kb$sugestão de resposta com ia$kb$,$kb$o cliente vê a nota interna?$kb$,$kb$como mudar status do chamado$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como criar um curso com módulos e aulas no E-Learning$kb$, $kb$Vá em E-Learning › Gerenciar cursos (/app/elearning/admin). O acesso é para administradores ou quem tem permissão de escrita no E-Learning. Clique em Novo curso e preencha Título (obrigatório), Slug, Descrição, URL da imagem de capa, Nível (Iniciante, Intermediário ou Avançado), Carga horária (min), Status (Rascunho ou Publicado) e Ordem. Com o curso selecionado, clique em Novo módulo (Título, Descrição, Ordem) e depois em Nova aula. Na aula, escolha o Tipo (Texto / Leitura, Vídeo do YouTube, Vimeo ou MP4, PDF ou Link externo) e informe Duração (min), Ordem e o conteúdo. Só os cursos Publicados aparecem em Meus cursos, onde o aluno usa Marcar como concluída em cada aula.$kb$, $kb$backend-elearning$kb$, ARRAY[$kb$como criar um curso$kb$,$kb$como adicionar aula em vídeo$kb$,$kb$como publicar um curso no e-learning$kb$,$kb$como montar módulos de treinamento$kb$,$kb$posso subir pdf como aula?$kb$,$kb$curso não aparece para os corretores$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como editar ou excluir um lançamento financeiro$kb$, $kb$Acesse Financeiro › Contas a pagar e receber (/app/financeiro). Na tabela, clique no ícone de lápis da linha para abrir a tela 'Editar lançamento' (/app/financeiro/<id>), altere o que precisar e clique em 'Salvar alterações'. Para apagar, clique no ícone de lixeira e confirme a pergunta 'Excluir este lançamento?'. A exclusão remove o lançamento de vez. Se você só quer tirá-lo dos totais, mude o Status para 'Cancelado': lançamentos cancelados não entram nos cards de Receitas, Despesas e Saldo. O módulo Financeiro fica disponível para os perfis Admin e Financeiro. O perfil Corretor não tem acesso.$kb$, $kb$backend-financeiro$kb$, ARRAY[$kb$como editar um lançamento no financeiro$kb$,$kb$como apagar uma conta a pagar$kb$,$kb$errei o valor de uma despesa, como corrigir$kb$,$kb$como excluir uma receita lançada errada$kb$,$kb$dá pra cancelar um lançamento sem apagar$kb$,$kb$onde altero um lançamento já criado$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como marcar uma conta como paga ou recebida$kb$, $kb$Em Financeiro › Contas a pagar e receber (/app/financeiro), clique no lápis do lançamento para abrir 'Editar lançamento'. No campo Status, escolha 'Pago' e preencha a 'Data de pagamento'. Depois clique em 'Salvar alterações'. Os status possíveis são Pendente, Pago, Atrasado e Cancelado. O card 'Em aberto' soma apenas os lançamentos com status Pendente ou Atrasado. Quando a receita é pendente ou atrasada e está vinculada a um contrato, a mesma tela também mostra a opção de cobrar via Mercado Pago.$kb$, $kb$backend-financeiro$kb$, ARRAY[$kb$como dar baixa em uma conta$kb$,$kb$como marcar despesa como paga$kb$,$kb$como registrar que recebi um pagamento$kb$,$kb$onde coloco a data de pagamento$kb$,$kb$como quitar um lançamento$kb$,$kb$como mudar status para pago no financeiro$kb$,$kb$como dar baixa numa conta paga$kb$,$kb$dar baixa em conta paga$kb$,$kb$como baixar um pagamento$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como verificar a inadimplência e marcar contas atrasadas$kb$, $kb$Em Financeiro › Contas a pagar e receber (/app/financeiro), clique no botão 'Verificar inadimplência', no topo da tela. O sistema procura todos os lançamentos com status Pendente e data de vencimento anterior a hoje e muda o status deles para 'Atrasado'. Ao terminar, aparece uma mensagem com a quantidade de lançamentos marcados ou o aviso 'Nenhum lançamento vencido pendente.'. Os atrasados aparecem com o selo vermelho 'Atrasado' na lista e continuam somando no card 'Em aberto'.$kb$, $kb$backend-financeiro$kb$, ARRAY[$kb$como ver quem está inadimplente$kb$,$kb$como marcar contas vencidas como atrasadas$kb$,$kb$o sistema marca atraso sozinho$kb$,$kb$como atualizar contas vencidas$kb$,$kb$botão verificar inadimplência faz o que$kb$,$kb$como achar lançamentos em atraso$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como buscar e filtrar lançamentos e ver o saldo$kb$, $kb$Em Financeiro › Contas a pagar e receber (/app/financeiro), o topo da tela mostra quatro cards: Receitas, Despesas, Saldo (receitas menos despesas) e Em aberto (pendentes e atrasados). Lançamentos cancelados ficam fora desses totais. Use o campo 'Buscar…' para encontrar lançamentos pela descrição ou pela categoria. Os botões Todos, Receitas e Despesas filtram a lista pelo tipo. A tabela traz Descrição, Categoria, Vencimento, Status e Valor, ordenada pelo vencimento mais recente.$kb$, $kb$backend-financeiro$kb$, ARRAY[$kb$como ver só as despesas$kb$,$kb$como filtrar receitas no financeiro$kb$,$kb$onde vejo o saldo do caixa$kb$,$kb$como pesquisar um lançamento$kb$,$kb$quanto tenho em aberto$kb$,$kb$como ver o total de receitas$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como classificar um lançamento por plano de contas, centro de custo e vínculos$kb$, $kb$Ao criar ou editar um lançamento em Financeiro › Contas a pagar e receber (botão 'Novo lançamento', /app/financeiro/novo), use a seção 'Classificação contábil' para escolher o Plano de contas e o Centro de custo. Só aparecem as contas e os centros que estiverem ativos. Na seção 'Vínculos (opcional)', você pode ligar o lançamento a um Contrato, a um Imóvel e a um Corretor. Os campos obrigatórios são Tipo (Receita ou Despesa), Descrição, Valor (R$) e Data de vencimento. A Categoria é texto livre de até 80 caracteres, por exemplo 'comissão' ou 'aluguel'. Se a imobiliária tiver campos personalizados para lançamentos, eles aparecem na seção 'Campos personalizados'.$kb$, $kb$backend-financeiro$kb$, ARRAY[$kb$como vincular um lançamento a um contrato$kb$,$kb$como colocar centro de custo no lançamento$kb$,$kb$onde escolho o plano de contas da despesa$kb$,$kb$como ligar uma receita a um imóvel$kb$,$kb$como associar lançamento ao corretor$kb$,$kb$como categorizar receitas e despesas$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como cadastrar centros de custo$kb$, $kb$Acesse Financeiro › Centros de custo (/app/financeiro/centros-custo). O endereço antigo /app/configuracoes/centros-custo redireciona para essa tela. Preencha o Código e o Nome (por exemplo Matriz ou Filial SP) e clique no botão '+'. Os dois campos são obrigatórios. Os centros cadastrados aparecem na lista abaixo, e o ícone de lixeira remove um centro. Eles servem para agrupar lançamentos por filial, equipe ou projeto e ficam disponíveis no campo 'Centro de custo' dos lançamentos e dos contratos.$kb$, $kb$backend-financeiro$kb$, ARRAY[$kb$como criar centro de custo$kb$,$kb$onde cadastro filiais no financeiro$kb$,$kb$como separar despesas por filial$kb$,$kb$como apagar um centro de custo$kb$,$kb$o que é centro de custo no imob365$kb$,$kb$como organizar lançamentos por equipe$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como montar o plano de contas$kb$, $kb$Acesse Financeiro › Plano de contas (/app/financeiro/plano-contas). O endereço antigo /app/configuracoes/plano-contas redireciona para essa tela. Preencha o Código e o Nome, escolha o tipo (Receita ou Despesa) e clique no botão '+'. Código e Nome são obrigatórios. A tabela mostra Código, Nome e Tipo de cada conta, e o ícone de lixeira remove a conta. As contas ativas aparecem no campo 'Plano de contas' dos lançamentos, ordenadas por código, para categorizar receitas e despesas nos relatórios contábeis.$kb$, $kb$backend-financeiro$kb$, ARRAY[$kb$como criar plano de contas$kb$,$kb$onde cadastro as contas contábeis$kb$,$kb$como adicionar uma conta de despesa$kb$,$kb$como categorizar para a contabilidade$kb$,$kb$como excluir uma conta do plano de contas$kb$,$kb$plano de contas fica onde$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como marcar uma comissão como paga$kb$, $kb$Acesse Financeiro › Comissões (/app/comissoes). Na linha de uma comissão com status 'A pagar', clique em 'Pagar'. A comissão passa para 'Paga' com a data de hoje, e o sistema cria automaticamente uma despesa já paga no Financeiro, com categoria 'Comissão' e descrição 'Comissão — nome do corretor'. Os cards do topo mostram os totais A pagar, Pagas e Total. Para filtrar, use os botões Todas, A pagar, Paga e Cancelada ou busque pelo corretor ou pelo número do contrato.$kb$, $kb$backend-financeiro$kb$, ARRAY[$kb$como pagar comissão do corretor$kb$,$kb$como dar baixa em comissão$kb$,$kb$pagar comissão gera despesa no financeiro$kb$,$kb$como marcar comissão como paga$kb$,$kb$onde vejo comissões a pagar$kb$,$kb$como registrar pagamento de comissão$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como editar, cancelar ou apagar uma comissão$kb$, $kb$Em Financeiro › Comissões (/app/comissoes), clique no lápis para editar a comissão (/app/comissoes/<id>). Lá você altera Contrato, Corretor, Percentual (%), Valor (R$), Status, Data prevista, Data de pagamento e Observações. Depois clique em 'Salvar alterações'. Para cancelar, use o botão 'X', que só aparece em comissões com status 'A pagar', e confirme 'Cancelar esta comissão?'. Para remover de vez, use a lixeira: a ação não pode ser desfeita. Cada contrato aceita só uma comissão. Se já existir uma, o sistema avisa 'Já existe uma comissão para este contrato'.$kb$, $kb$backend-financeiro$kb$, ARRAY[$kb$como cancelar uma comissão$kb$,$kb$como alterar o valor da comissão$kb$,$kb$como excluir comissão$kb$,$kb$dá pra ter duas comissões no mesmo contrato$kb$,$kb$como editar a porcentagem da comissão$kb$,$kb$como mudar o corretor da comissão$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como gerar a comissão a partir do contrato$kb$, $kb$A comissão é criada automaticamente quando um contrato com corretor responsável passa para o status 'Ativo'. O valor vem do campo 'Comissão (R$)'. Se ele estiver vazio, o sistema calcula pelo 'Comissão (%)' do contrato ou, na falta dele, pela comissão padrão do corretor. Para gerar manualmente, abra o contrato em Jurídico › Contratos e clique em 'Gerar comissão'. Você será levado ao formulário de nova comissão (/app/comissoes/novo), já preenchido com o contrato, o corretor e os valores sugeridos. Se o contrato já tiver comissão, o botão aparece como 'Comissão já gerada' e fica desabilitado.$kb$, $kb$backend-financeiro$kb$, ARRAY[$kb$como gerar comissão do contrato$kb$,$kb$a comissão é criada sozinha$kb$,$kb$por que o botão gerar comissão está desabilitado$kb$,$kb$como calcular comissão automaticamente$kb$,$kb$ativei o contrato e a comissão apareceu$kb$,$kb$de onde vem o valor da comissão$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como configurar a emissão de Nota Fiscal (Focus NFe)$kb$, $kb$Acesse Configurações › Nota Fiscal (/app/configuracoes/nota-fiscal). Só administradores podem fazer essa configuração. Antes, crie sua conta em focusnfe.com.br e registre lá o seu CNPJ e o certificado digital (e-CNPJ): o imob365 não guarda o seu certificado. No painel da Focus NFe, copie o Token de acesso (Integrações → API). De volta ao imob365, preencha Token de acesso, CNPJ do prestador, Inscrição municipal, Código IBGE do município (7 dígitos) e Item da lista de serviço; o item 10.05 é o padrão para corretagem. Ajuste as chaves 'Optante pelo Simples Nacional', 'Ambiente de produção' e 'Integração ativa' e clique em 'Salvar'. Comece em Homologação e só mude para Produção depois que uma nota de teste sair correta, porque em produção a nota tem valor fiscal real.$kb$, $kb$backend-financeiro$kb$, ARRAY[$kb$como configurar nota fiscal$kb$,$kb$como conectar focus nfe$kb$,$kb$onde coloco o token da focus nfe$kb$,$kb$como emitir NFS-e no imob365$kb$,$kb$qual item de serviço para corretagem$kb$,$kb$como sair da homologação para produção na nota fiscal$kb$,$kb$preciso de certificado digital para nota fiscal$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como emitir NFS-e de uma comissão$kb$, $kb$Acesse Financeiro › Comissões (/app/comissoes) e clique no lápis da comissão. Abaixo do formulário fica a seção 'Nota Fiscal'. Clique em 'Emitir nota fiscal' e preencha o Nome do tomador (quem recebe a nota), o CPF ou CNPJ (só números) e, se quiser, o E-mail. O valor da nota é sempre o valor da comissão. Confirme em 'Emitir nota fiscal'. Para emitir, a conta Focus NFe precisa estar conectada e ativa em Configurações › Nota Fiscal; se não estiver, a seção mostra o link 'Configurar Nota Fiscal'. Só os perfis Admin e Financeiro podem emitir.$kb$, $kb$backend-financeiro$kb$, ARRAY[$kb$como emitir nota fiscal da comissão$kb$,$kb$como gerar NFS-e$kb$,$kb$onde emito nota de corretagem$kb$,$kb$como emitir nota para o cliente$kb$,$kb$por que não aparece o botão emitir nota$kb$,$kb$quem pode emitir nota fiscal$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como acompanhar o status e baixar a nota fiscal emitida$kb$, $kb$As notas emitidas aparecem na seção 'Nota Fiscal' da tela de edição da comissão (Financeiro › Comissões › lápis). Cada nota mostra o tomador, o valor, o número e um selo de status: Processando, Autorizada, Erro ou Cancelada. Depois do envio, a nota fica em 'Processando' enquanto a prefeitura autoriza. Clique no botão de atualizar ao lado da nota para consultar o status de novo. Quando a nota for autorizada, aparece um botão com link externo para abrir o documento da NFS-e. Se der erro, a mensagem retornada aparece ao lado do valor.$kb$, $kb$backend-financeiro$kb$, ARRAY[$kb$minha nota está processando, o que faço$kb$,$kb$como ver se a nota foi autorizada$kb$,$kb$como baixar a NFS-e emitida$kb$,$kb$onde vejo o número da nota fiscal$kb$,$kb$nota fiscal deu erro, onde vejo o motivo$kb$,$kb$como atualizar status da nota$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como cadastrar uma locação$kb$, $kb$Uma locação é cadastrada como contrato do tipo 'Locação'. Vá em Jurídico › Contratos, clique em 'Novo contrato' (/app/contratos/novo) e escolha o Tipo 'Locação'. O imóvel e o corretor responsável são obrigatórios. Para acompanhar suas locações, acesse Imobiliário › Locação (/app/locacao). A tela lista os contratos de locação (número, imóvel, valor e status), as ordens de serviço abertas e tem o botão 'Ver repasses'. Nos contratos de Locação ou Administração aparecem ainda as seções de reajuste, garantias e 'Dados bancários do proprietário'.$kb$, $kb$backend-locacao$kb$, ARRAY[$kb$como cadastrar um aluguel$kb$,$kb$como registrar uma locação$kb$,$kb$onde ficam os contratos de aluguel$kb$,$kb$como criar contrato de locação$kb$,$kb$a tela de locação está vazia, o que faço$kb$,$kb$onde vejo os imóveis alugados$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como cadastrar os dados bancários do proprietário para o repasse$kb$, $kb$Abra o contrato de locação ou de administração em Jurídico › Contratos e clique no lápis. Role até a seção 'Dados bancários do proprietário', que é o destino do repasse do aluguel. Escolha o tipo de chave PIX (CPF/CNPJ, E-mail, Telefone ou Chave aleatória) e informe a Chave PIX, o Banco, a Agência e a Conta. Depois clique em 'Salvar', ou em 'Atualizar' se os dados já existirem. A seção só aparece em contratos do tipo Locação ou Administração, e os dados ficam visíveis apenas para admin e financeiro.$kb$, $kb$backend-locacao$kb$, ARRAY[$kb$onde coloco o pix do proprietário$kb$,$kb$como cadastrar conta bancária do locador$kb$,$kb$para onde vai o repasse do aluguel$kb$,$kb$como informar banco e agência do proprietário$kb$,$kb$dados bancários do dono do imóvel$kb$,$kb$como alterar a chave pix do repasse$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como gerar os repasses do mês manualmente e dar baixa$kb$, $kb$Acesse Financeiro › Repasses (locação) (/app/locacao/repasses). Os repasses são gerados automaticamente todo dia 1º para cada contrato de locação ativo. Para gerar na hora, clique em 'Gerar agora': o sistema informa quantos repasses criou e quantos já existiam. Quando o inquilino pagar, clique em 'Recebido' na linha do repasse. Depois de transferir ao proprietário, clique em 'Repassar'. O status vai de Pendente para Aluguel recebido e depois para Repassado, e cada etapa grava a data. Os cards mostram os totais 'Aguardando recebimento', 'Recebido, a repassar' e 'Repassado'.$kb$, $kb$backend-locacao$kb$, ARRAY[$kb$como gerar repasse agora$kb$,$kb$o repasse não apareceu, como gerar$kb$,$kb$como marcar aluguel como recebido$kb$,$kb$como confirmar que repassei ao proprietário$kb$,$kb$quando os repasses são criados$kb$,$kb$botão gerar agora dos repasses$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como editar um repasse e ajustar a taxa de administração$kb$, $kb$Em Financeiro › Repasses (locação) (/app/locacao/repasses), clique no lápis do repasse para abrir 'Editar repasse'. Você pode alterar o Valor do aluguel (R$), a Taxa de administração (%) e Outros descontos (R$). O 'Repasse líquido (calculado)' é atualizado sozinho pela conta: aluguel menos a taxa de administração menos os outros descontos. Na mesma tela você muda o Status, a Data de recebimento, a Data do repasse e as Observações. Depois clique em 'Salvar alterações'. Para apagar um repasse, use a lixeira na lista; a ação não pode ser desfeita.$kb$, $kb$backend-locacao$kb$, ARRAY[$kb$como mudar a taxa de administração do repasse$kb$,$kb$como descontar um valor do repasse$kb$,$kb$como corrigir valor do aluguel no repasse$kb$,$kb$como é calculado o repasse líquido$kb$,$kb$como excluir um repasse$kb$,$kb$como editar repasse do proprietário$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como criar e editar modelos de contrato$kb$, $kb$Acesse Jurídico › Modelos de contrato (/app/contratos/modelos) e clique em 'Novo modelo'. Informe o Nome (por exemplo Contrato de Locação Residencial) e o Tipo, e escreva o texto no editor 'Conteúdo do modelo'. O editor tem negrito, itálico, sublinhado, títulos, alinhamento e listas. Clique nas variáveis exibidas acima do editor para inserir campos automáticos, como {{contrato.numero}}, {{contrato.valor}}, {{imovel.endereco}}, {{tenant.nome}}, {{partes.locador}} e {{partes.locatario}}. Mantenha marcada a opção 'Modelo ativo (disponível para uso em contratos)' e clique em 'Salvar modelo'. Para alterar um modelo existente, use 'Editar'. Para removê-lo, use a lixeira.$kb$, $kb$backend-contratos$kb$, ARRAY[$kb$como criar modelo de contrato$kb$,$kb$como usar variáveis no contrato$kb$,$kb$como cadastrar meu próprio contrato padrão$kb$,$kb$como editar um modelo de contrato$kb$,$kb$como colocar nome do locatário automático no contrato$kb$,$kb$onde ficam os templates de contrato$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como usar a Biblioteca de modelos prontos$kb$, $kb$Acesse Jurídico › Biblioteca de modelos (/app/contratos/modelos/biblioteca) ou clique em 'Biblioteca de modelos' na tela Modelos de contrato. Estão disponíveis: Compra e Venda — Padrão, Locação Residencial, Locação Comercial, Parceria entre Imobiliárias, Administração de Imóvel para Locação, Autorização de Venda com Exclusividade, Permuta de Imóveis e Distrato / Rescisão Amigável. Clique em 'Usar este modelo' para copiar o modelo para a sua conta. Ele aparece ativo em Modelos de contrato, onde você pode editá-lo livremente.$kb$, $kb$backend-contratos$kb$, ARRAY[$kb$tem modelo de contrato pronto$kb$,$kb$como usar contrato de locação pronto$kb$,$kb$onde acho modelo de distrato$kb$,$kb$biblioteca de contratos do imob365$kb$,$kb$como copiar um modelo pronto$kb$,$kb$tem modelo de autorização de venda com exclusividade$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como imprimir ou baixar o contrato em PDF$kb$, $kb$Abra o contrato em Jurídico › Contratos (lápis) e clique em 'Imprimir' no topo. Você vai para a tela 'Imprimir contrato' (/app/contratos/<id>/imprimir). No campo Modelo, escolha um dos modelos ativos. O sistema já sugere o modelo do mesmo tipo do contrato. Confira a prévia, em que as variáveis já vêm preenchidas com os dados do contrato, do imóvel, das partes e da imobiliária. Depois clique em 'Imprimir' ou em 'Baixar PDF'. Se não houver nenhum modelo ativo, a tela mostra um link para cadastrar um em Modelos de contrato.$kb$, $kb$backend-contratos$kb$, ARRAY[$kb$como imprimir contrato$kb$,$kb$como gerar pdf do contrato$kb$,$kb$como baixar o contrato preenchido$kb$,$kb$como escolher o modelo na impressão$kb$,$kb$como salvar contrato em pdf$kb$,$kb$o contrato não tem modelo para imprimir$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como encontrar, filtrar ou excluir contratos$kb$, $kb$Acesse Jurídico › Contratos (/app/contratos). O topo mostra os cards Total, Ativos, Rascunhos e Valor total ativo (com a quantidade de contratos assinados). Use 'Buscar por número ou tipo…' e os filtros de status (Rascunho, Ativo, Encerrado, Rescindido, Cancelado) e de tipo (Venda, Locação, Permuta, Parceria, Administração, Prestação de Serviço, Exclusividade, Captação, Outro). 'Limpar filtros' zera tudo. A coluna Assinatura mostra Não enviado, Aguardando, Parcial ou Assinado. O lápis abre o contrato, e a lixeira exclui depois da confirmação; a exclusão não pode ser desfeita. O perfil Corretor tem acesso de leitura ao Jurídico.$kb$, $kb$backend-contratos$kb$, ARRAY[$kb$como achar um contrato$kb$,$kb$como filtrar contratos ativos$kb$,$kb$como excluir um contrato$kb$,$kb$como ver contratos assinados$kb$,$kb$como buscar contrato pelo número$kb$,$kb$como ver só contratos de locação$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como consultar o Painel de Contratos$kb$, $kb$Acesse Jurídico › Painel (/app/contratos/painel). Os cards mostram contratos Ativos, Vencidos, Vence em até 30 dias, 31–60 dias e 61–90 dias. O bloco 'Dashboard financeiro da carteira' traz Valor da carteira ativa, Tempo médio de contrato, Receita prevista, Receita realizada, Garantias vencendo e Reajustes pendentes, esses dois últimos considerando os próximos 30 dias. Mais abaixo aparecem os contratos ativos por tipo e a lista de contratos a vencer nos próximos 90 dias e vencidos, com o corretor e os dias restantes. O botão 'Verificar SLA agora' roda na hora a verificação de alertas de contratos e cartórios.$kb$, $kb$backend-contratos$kb$, ARRAY[$kb$onde vejo contratos vencendo$kb$,$kb$painel jurídico mostra o que$kb$,$kb$quantos contratos vencem esse mês$kb$,$kb$como ver valor da carteira de contratos$kb$,$kb$como ver reajustes pendentes$kb$,$kb$botão verificar SLA agora$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como adicionar as partes de um contrato$kb$, $kb$Abra o contrato em Jurídico › Contratos (lápis) e vá à seção 'Partes do contrato'. Escolha o Papel: Vendedor, Comprador, Locador, Locatário, Fiador, Procurador, Testemunha, Corretor, Advogado, Administrador ou Outro. Informe Nome, CPF/CNPJ, Email e Telefone e clique no botão '+'. O nome é obrigatório. Em 'Qualificação e participação (opcional)', você pode preencher Participação (%), Responsabilidade, Nacionalidade, Estado civil, Profissão e Endereço. As partes alimentam as variáveis dos modelos de contrato e a lista de signatários da assinatura eletrônica.$kb$, $kb$backend-contratos$kb$, ARRAY[$kb$como cadastrar comprador no contrato$kb$,$kb$como adicionar fiador$kb$,$kb$como incluir testemunha no contrato$kb$,$kb$onde coloco locador e locatário$kb$,$kb$como remover uma parte do contrato$kb$,$kb$como colocar estado civil e profissão da parte$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como gerar o resumo executivo com IA e ver o histórico do contrato$kb$, $kb$Na tela do contrato (Jurídico › Contratos › lápis), a seção 'Resumo executivo (IA)' tem o botão 'Gerar resumo'. Ele cria um resumo curto, de 3 a 4 frases, baseado apenas nos dados e cláusulas reais daquele contrato. Para refazer, clique em 'Gerar novamente'. Logo abaixo, a seção 'Histórico' lista as últimas 50 alterações dos dados gerais do contrato (Criado, Atualizado, Removido). Apenas administradores podem ver o histórico.$kb$, $kb$backend-contratos$kb$, ARRAY[$kb$como fazer resumo do contrato com ia$kb$,$kb$o imob365 resume contrato$kb$,$kb$como ver quem alterou o contrato$kb$,$kb$histórico de alterações do contrato$kb$,$kb$por que não vejo o histórico do contrato$kb$,$kb$resumo executivo do contrato$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como registrar e acompanhar processos em cartório$kb$, $kb$Acesse Jurídico › Cartórios (/app/cartorios) e clique em 'Novo registro'. Preencha Tipo (Escritura, Registro, Averbação, Procuração ou Outro), Contrato, Status, Cartório, Cidade, UF, Protocolo, Data protocolo, Custas (R$) e Observações, e clique em 'Salvar'. Na lista, você muda o status direto pelo seletor de cada registro: Pendente, Protocolado, Em exigência, Registrado ou Cancelado. Um registro Pendente, Protocolado ou Em exigência sem atualização há mais de 15 dias gera uma tarefa de alerta de SLA, de prioridade alta, para o responsável.$kb$, $kb$backend-juridico$kb$, ARRAY[$kb$como acompanhar escritura no cartório$kb$,$kb$como registrar protocolo de cartório$kb$,$kb$onde controlo averbação$kb$,$kb$como lançar custas de cartório$kb$,$kb$cartório em exigência, como marcar$kb$,$kb$alerta de cartório parado$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como conectar a conta DocuSign$kb$, $kb$Acesse Configurações › Assinatura eletrônica (/app/configuracoes/assinatura-eletronica). Só administradores têm acesso. Em admin.docusign.com, entre em Integrações → Apps e Chaves e clique em 'Adicionar App e Chave de Integração'. Cole no campo 'URI de redirecionamento do OAuth' o endereço exibido na tela do imob365 (há um botão de copiar). Em seguida, gere uma Secret Key, que só aparece uma vez. No imob365, preencha 'Integration Key (Client ID)' e 'Secret Key', clique em 'Salvar' e depois em 'Conectar DocuSign' para autorizar. O DocuSign pode exigir a etapa de Go-Live da chave antes de funcionar em produção. Para desfazer, use 'Desconectar conta' ou 'Remover App configurado'.$kb$, $kb$backend-juridico$kb$, ARRAY[$kb$como integrar docusign$kb$,$kb$como conectar docusign no imob365$kb$,$kb$onde coloco integration key do docusign$kb$,$kb$erro ao conectar docusign$kb$,$kb$o que é go-live do docusign$kb$,$kb$como desconectar docusign$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como configurar Clicksign, ZapSign ou outro provedor de assinatura$kb$, $kb$Em Configurações › Assinatura eletrônica (/app/configuracoes/assinatura-eletronica), que é acesso apenas de administradores, vá à seção 'Provedor de assinatura eletrônica'. Escolha o Provedor (Clicksign, ZapSign, gov.br, ICP-Brasil ou Outro) e informe a 'API Key / Token' e o 'Segredo do webhook (HMAC)'. Ligue 'Integração ativa' e clique em 'Salvar'. Depois, copie a 'URL do webhook' exibida e cadastre-a no painel do provedor: é por ela que a confirmação de assinatura chega ao imob365. Cada imobiliária usa a própria conta no provedor. Nesses provedores, o envio do documento ao signatário é feito por fora; só o DocuSign envia o envelope direto pelo imob365.$kb$, $kb$backend-juridico$kb$, ARRAY[$kb$como configurar clicksign$kb$,$kb$como integrar zapsign$kb$,$kb$onde coloco a api key da assinatura$kb$,$kb$url do webhook da assinatura$kb$,$kb$como usar gov.br para assinar contrato$kb$,$kb$assinatura eletrônica não confirma$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como enviar um contrato para assinatura pelo DocuSign$kb$, $kb$Com o DocuSign conectado, abra o contrato em Jurídico › Contratos (lápis) e vá ao painel 'Assinatura eletrônica'. Na 'Etapa 1: Anexar PDF oficial', clique em 'Gerar PDF do contrato' para abrir a tela de impressão e baixar o PDF. Depois volte e clique em 'Anexar PDF gerado'. Em seguida, clique em 'Solicitar assinatura' ao lado de cada parte: o envelope vai para o DocuSign e a parte recebe o e-mail de assinatura. O botão fica desabilitado enquanto não houver PDF anexado, e as partes precisam estar cadastradas antes. O status muda sozinho para Assinado quando o provedor confirma.$kb$, $kb$backend-juridico$kb$, ARRAY[$kb$como mandar contrato pro docusign$kb$,$kb$como enviar contrato para assinar$kb$,$kb$solicitar assinatura está desabilitado$kb$,$kb$como anexar pdf para assinatura$kb$,$kb$o cliente não recebeu e-mail de assinatura$kb$,$kb$como pedir assinatura do locatário$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como criar modelos de checklist de documentos$kb$, $kb$Acesse Imobiliário › Checklist de documentos (/app/configuracoes/checklist). Em 'Modelos', digite o nome (por exemplo Venda residencial) e clique em 'Criar'. Em 'Itens por modelo', escolha o modelo, a etapa (proposta, documentacao, financiamento, assinatura ou registro) e o nome do documento (por exemplo RG do comprador) e clique em '+'. Para aplicar o modelo, selecione-o no campo 'Template de checklist' ao criar o contrato ou use 'Aplicar' no checklist do contrato. Ao remover um modelo, todos os itens dele também são apagados.$kb$, $kb$backend-contratos$kb$, ARRAY[$kb$como criar checklist de documentos$kb$,$kb$como cadastrar lista de documentos padrão$kb$,$kb$como configurar documentos por etapa$kb$,$kb$como aplicar checklist no contrato$kb$,$kb$onde edito o modelo de checklist$kb$,$kb$como apagar um modelo de checklist$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como mudar de plano ou fazer upgrade$kb$, $kb$Acesse Configurações › Plano & Contratação (/app/contratacao). A tela abre já com o seu plano atual selecionado. Em '1 Selecione o Plano Base', escolha Mensal ou Anual e clique no plano desejado. Cada cartão mostra o preço por mês, a Cota de Imóveis e os Módulos inclusos; no anual, aparece também o valor cobrado anualmente. Em '2 Selecione os Serviços & Módulos Disponíveis', ligue ou desligue os módulos opcionais. Em '3 Dados para nota fiscal', informe o CPF ou CNPJ e a Razão Social ou Nome Completo. Confira o 'Resumo do Faturamento' e clique no botão de confirmação.$kb$, $kb$backend-financeiro$kb$, ARRAY[$kb$como fazer upgrade de plano$kb$,$kb$como trocar de plano$kb$,$kb$onde contrato um plano melhor$kb$,$kb$como mudar do plano mensal para anual$kb$,$kb$quanto custa cada plano$kb$,$kb$onde vejo meu plano atual$kb$,$kb$como fazer upgrade$kb$,$kb$como assinar um plano$kb$,$kb$como pagar a assinatura$kb$,$kb$como mudar de plano$kb$,$kb$posso pagar no boleto ou pix?$kb$,$kb$como contratar o business$kb$,$kb$meu plano não mudou depois de pagar$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como pagar o plano pelo Mercado Pago$kb$, $kb$Em Configurações › Plano & Contratação (/app/contratacao), escolha um plano pago, preencha o CPF ou CNPJ e a Razão Social ou Nome Completo para a nota fiscal e clique em 'Ir para pagamento no Mercado Pago'. Você é redirecionado ao Mercado Pago para concluir o pagamento com segurança. O plano só é ativado depois que o Mercado Pago confirma o pagamento. Até lá, o plano anterior continua valendo. Se aparecer 'Este plano ainda não tem checkout automático configurado', fale com o suporte.$kb$, $kb$backend-financeiro$kb$, ARRAY[$kb$como pagar a assinatura do imob365$kb$,$kb$como pagar o plano$kb$,$kb$paguei e o plano não mudou$kb$,$kb$forma de pagamento do plano$kb$,$kb$onde coloco o cpf ou cnpj da nota do plano$kb$,$kb$como assinar um plano pago$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como ativar módulos opcionais e quanto custa um módulo extra$kb$, $kb$Em Configurações › Plano & Contratação (/app/contratacao), na etapa '2 Selecione os Serviços & Módulos Disponíveis', ligue os módulos opcionais que quiser. Os módulos básicos já vêm inclusos e não podem ser desligados. Cada plano dá direito a uma quantidade de módulos opcionais, que pode ser ilimitada. Os módulos acima da cota aparecem no resumo como 'Módulos Excedentes', a R$ 29 por mês cada, como valor de referência que ainda não entra na cobrança automática do Mercado Pago. A seleção é salva ao confirmar a contratação. Depois, os módulos ativos aparecem no menu para os perfis com permissão.$kb$, $kb$backend-financeiro$kb$, ARRAY[$kb$como ativar um módulo$kb$,$kb$quanto custa módulo extra$kb$,$kb$como liberar o módulo financeiro$kb$,$kb$quantos módulos meu plano tem$kb$,$kb$como desligar um módulo$kb$,$kb$por que um módulo não aparece no menu$kb$,$kb$como ativar o módulo financeiro$kb$,$kb$como habilitar módulos$kb$,$kb$cota de módulos atingida$kb$,$kb$por que o menu jurídico não aparece$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como voltar para o plano Free ou contratar o plano Business$kb$, $kb$Em Configurações › Plano & Contratação (/app/contratacao), selecione o plano Free, preencha os dados de nota fiscal e clique em 'Confirmar e Ativar Assinatura'. O plano gratuito entra em vigor na hora, sem cobrança, e aparece a tela 'Plano atualizado!' com os botões 'Ver módulos ativos' e 'Ir para o Dashboard'. O plano Business não tem checkout automático: ao selecioná-lo, o botão vira 'Falar com vendas' e abre um e-mail para contato@imob365.com.br.$kb$, $kb$backend-financeiro$kb$, ARRAY[$kb$como voltar para o plano gratuito$kb$,$kb$como fazer downgrade$kb$,$kb$como contratar o plano business$kb$,$kb$plano free é cobrado$kb$,$kb$como falar com vendas do imob365$kb$,$kb$como cancelar o plano pago$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como duplicar um imóvel$kb$, $kb$Acesse o menu Imobiliário › Publicar Imóveis (/app/imoveis). Na linha do imóvel, na coluna Ações, clique no ícone de cópia (Duplicar anúncio). O sistema cria um novo imóvel com o título “(cópia)” no final, com as mesmas fotos e dados, mas como Rascunho, não publicado, sem código interno e sem destaque. Depois é só abrir a cópia, ajustar o que for diferente e clicar em Publicar imóvel. Na mesma coluna ficam o lápis (Editar) e a lixeira (Excluir), e a exclusão não pode ser desfeita.$kb$, $kb$backend-imoveis$kb$, ARRAY[$kb$como duplico um imóvel$kb$,$kb$dá pra copiar um anúncio$kb$,$kb$como clonar um imóvel parecido$kb$,$kb$quero criar um imóvel a partir de outro$kb$,$kb$tem botão de duplicar anúncio$kb$,$kb$como faço uma cópia do imóvel$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como publicar ou despublicar um imóvel no site$kb$, $kb$Abra o imóvel em Imobiliário › Publicar Imóveis (/app/imoveis) clicando no título ou no lápis. No fim do formulário, na barra fixa, clique em Publicar imóvel. Com isso o status passa a ser Ativo e o imóvel aparece na busca pública (/buscar) e na própria página dele. Para tirar do ar, clique em Despublicar, e o status vira Inativo. Para só gravar sem mudar a publicação, use Salvar rascunho (imóvel novo) ou Salvar alterações. O botão Ver no site, no topo da página do imóvel, abre o anúncio público.$kb$, $kb$backend-imoveis$kb$, ARRAY[$kb$como publico meu imóvel$kb$,$kb$como tiro o imóvel do ar$kb$,$kb$como despublicar um anúncio$kb$,$kb$meu imóvel não aparece no site$kb$,$kb$como deixar o imóvel visível na busca$kb$,$kb$onde fica o botão publicar imóvel$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como marcar um imóvel como vendido, alugado ou reservado$kb$, $kb$Abra o imóvel em Imobiliário › Publicar Imóveis (/app/imoveis) e vá até a seção Situação do imóvel. Clique em Status comercial (avançado) e escolha entre Rascunho, Ativo, Inativo, Vendido, Alugado ou Reservado. Depois clique em Salvar alterações. Fora do status Ativo, o imóvel não aparece na busca pública, porque só imóveis publicados com status Ativo ficam visíveis no site. O status também aparece na coluna Status da lista de imóveis.$kb$, $kb$backend-imoveis$kb$, ARRAY[$kb$como marco imóvel como vendido$kb$,$kb$como coloco alugado no imóvel$kb$,$kb$onde mudo o status do imóvel$kb$,$kb$como reservar um imóvel no sistema$kb$,$kb$imóvel vendido ainda aparece no site$kb$,$kb$como inativar um imóvel$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como enviar, reordenar fotos e escolher a capa do imóvel$kb$, $kb$Abra o imóvel em Imobiliário › Publicar Imóveis (/app/imoveis). Na seção Fotos, clique em Adicionar fotos, que aceita várias imagens de uma vez e comprime automaticamente antes do envio. Para mudar a ordem, arraste as fotos (a mensagem Ordem atualizada confirma). Para escolher a foto de destaque do anúncio, clique em Tornar capa na foto desejada. A primeira foto enviada já vira capa automaticamente. Para apagar uma foto, use o ícone de lixeira e confirme. No cadastro de um imóvel novo, as fotos são a primeira seção do formulário.$kb$, $kb$backend-imoveis$kb$, ARRAY[$kb$como coloco fotos no imóvel$kb$,$kb$como mudo a ordem das fotos$kb$,$kb$como escolher a foto de capa$kb$,$kb$como apagar foto do anúncio$kb$,$kb$dá pra subir várias fotos de uma vez$kb$,$kb$como trocar a foto principal do imóvel$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como aplicar marca d'água nas fotos do imóvel$kb$, $kb$Antes de tudo, cadastre a logo da imobiliária em Site › Site da imobiliária (/app/site), na parte de marca. Depois abra o imóvel em Imobiliário › Publicar Imóveis e, na seção Marca d'água, ative “Aplicar a logo da imobiliária sobre as fotos deste imóvel” e salve. Daí em diante, as fotos novas já sobem com a marca. Para as fotos que já estavam no imóvel, use o botão Aplicar marca d'água em todas as fotos, na seção Fotos. Se desligar a opção e salvar, aparece o botão Remover marca d'água de todas as fotos. As fotos originais nunca são perdidas.$kb$, $kb$backend-imoveis$kb$, ARRAY[$kb$como coloco marca d'água nas fotos$kb$,$kb$como proteger as fotos do imóvel contra cópia$kb$,$kb$como colocar minha logo nas fotos$kb$,$kb$como tirar a marca d'água$kb$,$kb$por que a marca d'água não aparece$kb$,$kb$marca d'água precisa de logo?$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como cadastrar um imóvel com o assistente passo a passo$kb$, $kb$Em Imobiliário › Publicar Imóveis (/app/imoveis), clique em Cadastrar com assistente (/app/imoveis/assistente). O assistente divide o cadastro em etapas: Fotos, Informações, Valores e medidas, Endereço, Condições, Corretor, Marca d'água, Campos extras, Publicar e Redes sociais. Use Próximo e Voltar para navegar. As fotos e o rascunho ficam salvos desde o início, e aparece o aviso Progresso salvo. Na etapa Publicar, clique em Publicar imóvel para colocar o anúncio no ar.$kb$, $kb$backend-imoveis$kb$, ARRAY[$kb$tem um jeito mais fácil de cadastrar imóvel$kb$,$kb$como usar o assistente de cadastro$kb$,$kb$cadastro de imóvel passo a passo$kb$,$kb$onde fica cadastrar com assistente$kb$,$kb$perco o que digitei se sair do cadastro$kb$,$kb$como cadastrar imóvel guiado$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como gerar descrição e título do anúncio com IA$kb$, $kb$No formulário do imóvel (novo ou em edição, em Imobiliário › Publicar Imóveis), logo abaixo do campo Descrição, fica o Assistente IA do anúncio. Escolha o Tom de voz (Profissional, Acolhedor, Alto padrão ou Objetivo) e clique em Gerar descrição, Sugerir títulos, Post para redes ou Otimizar SEO (Tags). As sugestões de título podem ser aplicadas com um clique, e o post e as tags têm botão Copiar. Quanto mais dados preenchidos (tipo, quartos, área, bairro), melhor o resultado. Se você editar a descrição enquanto a IA gera o texto, a sugestão não substitui o que você escreveu.$kb$, $kb$backend-imoveis$kb$, ARRAY[$kb$como gerar descrição com inteligência artificial$kb$,$kb$a ia escreve o anúncio pra mim$kb$,$kb$como pedir sugestão de título$kb$,$kb$como gerar texto pra instagram do imóvel$kb$,$kb$onde fica o assistente ia do anúncio$kb$,$kb$como melhorar o seo do imóvel$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como importar imóveis ou leads em massa por planilha (CSV)$kb$, $kb$Acesse Imobiliário › Importar imóveis (/app/imoveis/importar). Disponível para administradores e corretores. Em O que importar, escolha Imóveis ou Leads e clique em Baixar modelo (CSV). Preencha no Excel ou Google Sheets, exporte como CSV e cole o conteúdo no campo Cole o conteúdo do CSV aqui. O separador é vírgula, sem aspas internas. Clique em Importar e veja quantos foram importados e quantos falharam. O modelo de imóveis tem titulo, tipo, finalidade, preco, quartos, banheiros, vagas, endereco_cidade e endereco_uf. O de leads tem nome, email, telefone, origem e mensagem. Depois abra cada imóvel importado para completar fotos e demais dados.$kb$, $kb$backend-imoveis$kb$, ARRAY[$kb$como importo vários imóveis de uma vez$kb$,$kb$dá pra subir planilha de imóveis$kb$,$kb$como importar leads de uma planilha$kb$,$kb$onde baixo o modelo csv$kb$,$kb$como migrar meus imóveis de outro sistema$kb$,$kb$importação em massa de imóveis$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como comparar imóveis lado a lado$kb$, $kb$Em Imobiliário › Publicar Imóveis (/app/imoveis), clique em Comparar (/app/imoveis/comparar). No campo Buscar imóvel para adicionar…, pesquise e adicione até 4 imóveis. O contador mostra quantos estão selecionados. A tabela compara Preço, Condomínio, IPTU, Tipo, Finalidade, Área útil, Área total, Quartos, Suítes, Banheiros, Vagas, Cidade, Bairro, Aceita permuta e Aceita financiamento. O sistema marca automaticamente os selos Melhor preço, Maior área e Mais quartos.$kb$, $kb$backend-imoveis$kb$, ARRAY[$kb$como comparo dois imóveis$kb$,$kb$tem comparador de imóveis$kb$,$kb$quantos imóveis posso comparar$kb$,$kb$como mostrar imóveis lado a lado pro cliente$kb$,$kb$onde fica o comparar imóveis$kb$,$kb$comparar preço e área de imóveis$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como destacar um imóvel e atualizar a localização no mapa$kb$, $kb$Abra o imóvel em Imobiliário › Publicar Imóveis (/app/imoveis). Na seção Destaque & localização, clique em Marcar como destaque, e o botão passa a mostrar Em destaque (clique de novo para desmarcar). Para o pin no mapa ficar no lugar certo, preencha o endereço (logradouro, número, bairro, cidade e UF), salve e clique em Atualizar coordenadas (mapa). As coordenadas encontradas aparecem ao lado do botão. Sem endereço preenchido, o sistema avisa para preencher primeiro.$kb$, $kb$backend-imoveis$kb$, ARRAY[$kb$como coloco imóvel em destaque$kb$,$kb$como destacar um anúncio$kb$,$kb$meu imóvel está no lugar errado do mapa$kb$,$kb$como atualizar a localização do imóvel$kb$,$kb$como gerar coordenadas do imóvel$kb$,$kb$pin do mapa errado$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como cadastrar um empreendimento/lançamento e o espelho de unidades$kb$, $kb$Acesse Imobiliário › Empreendimentos (/app/empreendimentos). Digite o nome em Nome do empreendimento e clique em Novo. Clique no nome para abrir e preencher Nome, Construtora, Fase (Lançamento, Em obras ou Pronto), Entrega prevista e Descrição. Os campos são salvos ao sair de cada um. Marque Publicar no site para exibir o empreendimento. Em Fotos do empreendimento, use Adicionar fotos. No Espelho de unidades, informe Bloco, Nº, Andar, Área e Preço, clique em + e defina o status de cada unidade (disponível, reservada, vendida ou bloqueada). Cada unidade tem o botão Simular financiamento (Simulador SAC, com Entrada %, Prazo em meses e Juros a.a.), e a seção Reservas ativas lista as reservas.$kb$, $kb$backend-imoveis$kb$, ARRAY[$kb$como cadastro um lançamento$kb$,$kb$como criar empreendimento$kb$,$kb$como montar o espelho de unidades$kb$,$kb$como marcar unidade como vendida$kb$,$kb$como simular financiamento de unidade$kb$,$kb$como publicar empreendimento no site$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como criar campos personalizados nos formulários$kb$, $kb$Acesse Configurações › Campos personalizados (/app/configuracoes/campos). Somente administradores. Em Formulário, escolha Imóveis ou Lançamentos financeiros. Preencha o Rótulo (ex.: Vista para o mar) e o Tipo (Texto, Número, Sim / Não, Seleção ou Data). No tipo Seleção, informe as opções separadas por vírgula. Clique em Adicionar. Os campos de imóveis aparecem no cadastro do imóvel, na seção Campos personalizados (no assistente, etapa Campos extras).$kb$, $kb$backend-geral$kb$, ARRAY[$kb$como adiciono um campo novo no cadastro de imóvel$kb$,$kb$dá pra criar campo personalizado$kb$,$kb$como incluir vista para o mar no cadastro$kb$,$kb$onde configuro campos extras$kb$,$kb$como criar campo de seleção$kb$,$kb$campos customizados no imóvel$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como ver os detalhes de um lead e registrar anotações$kb$, $kb$Em Imobiliário › Leads (/app/leads), clique no card do lead para abrir a ficha. Ela mostra data e origem, os contatos (e-mail, telefone e link direto de WhatsApp), o imóvel de interesse e a mensagem enviada. Em Histórico, escreva no campo Adicionar uma nota… e clique em Adicionar nota. A ficha também traz Visitas, Conversa com o lead, Tarefas e lembretes, Preferências e match de imóveis e a Linha do tempo unificada. Na lateral ficam Origem (UTM), Etapa e Corretor responsável, e o botão Excluir fica no topo.$kb$, $kb$backend-leads$kb$, ARRAY[$kb$como abro a ficha do lead$kb$,$kb$onde vejo os dados do lead$kb$,$kb$como anotar algo no lead$kb$,$kb$onde fica o histórico do lead$kb$,$kb$como chamar o lead no whatsapp$kb$,$kb$de onde veio esse lead$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como mudar a etapa de um lead$kb$, $kb$Em Imobiliário › Leads (/app/leads), o funil tem as colunas Novos, Em contato, Visita, Proposta, Ganho e Perdido. Arraste o card do lead até a nova coluna. Outra forma é abrir a ficha do lead e trocar o campo Etapa na lateral direita. Toda mudança de etapa fica registrada no histórico do lead. Use a busca por nome, e-mail ou telefone para achar o lead rapidamente.$kb$, $kb$backend-leads$kb$, ARRAY[$kb$como mudo o lead de etapa$kb$,$kb$como mover lead no funil$kb$,$kb$como marcar lead como ganho$kb$,$kb$como marcar lead perdido$kb$,$kb$arrastar lead no kanban$kb$,$kb$como avançar o lead pra proposta$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como atribuir um lead a um corretor$kb$, $kb$Abra a ficha do lead em Imobiliário › Leads (/app/leads) clicando no card. Na lateral direita, no campo Corretor responsável, escolha o corretor ou Sem corretor para remover. A atribuição fica registrada no histórico (ex.: Atribuído para Fulano), e o nome do corretor aparece no card do lead no funil. Para que os leads novos sejam distribuídos automaticamente, configure a Distribuição.$kb$, $kb$backend-leads$kb$, ARRAY[$kb$como passo um lead pra outro corretor$kb$,$kb$como atribuir lead$kb$,$kb$como trocar o corretor do lead$kb$,$kb$como escolher o responsável pelo lead$kb$,$kb$lead sem corretor$kb$,$kb$como transferir lead$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como ativar a distribuição automática de leads (rodízio)$kb$, $kb$Em Imobiliário › Leads (/app/leads), clique no botão Distribuição (/app/leads/configuracao). Ative a chave Distribuição automática (round-robin) e clique em Salvar. A partir daí, cada lead novo recebido pelo site é atribuído ao próximo corretor da fila. A seção Fila atual mostra os corretores ativos e indica quem foi o último a receber. Se não houver corretor ativo, use o link Cadastrar corretores.$kb$, $kb$backend-leads$kb$, ARRAY[$kb$como distribuir leads automaticamente$kb$,$kb$tem rodízio de leads entre corretores$kb$,$kb$como configurar round robin$kb$,$kb$quem recebe o próximo lead$kb$,$kb$como dividir leads entre a equipe$kb$,$kb$distribuição automática de leads$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como adicionar leads manualmente$kb$, $kb$A tela Imobiliário › Leads (/app/leads) recebe automaticamente os leads enviados pelo site e não tem um botão de novo lead. Para incluir leads por conta própria, use Imobiliário › Importar imóveis (/app/imoveis/importar), escolha Leads em O que importar, baixe o modelo CSV (nome, email, telefone, origem, mensagem), preencha e importe. Se você tem plano Pro ou Business, também pode criar um lead a partir de um anúncio do Facebook Marketplace em Imobiliário › Captação Automática, no botão Importar anúncio. Leads de campanhas do Facebook e Instagram chegam sozinhos depois que você conecta sua Página.$kb$, $kb$backend-leads$kb$, ARRAY[$kb$como cadastro um lead manualmente$kb$,$kb$como criar lead na mão$kb$,$kb$não acho botão de novo lead$kb$,$kb$como incluir um cliente no funil$kb$,$kb$como adicionar contato como lead$kb$,$kb$como colocar lead que veio por telefone$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como cadastrar preferências do lead e ver imóveis compatíveis$kb$, $kb$Na ficha do lead (Imobiliário › Leads, clique no card), vá até Preferências e match de imóveis. Preencha Finalidade (Qualquer, Venda ou Locação), Tipos (separados por vírgula), Bairros, Cidades, Preço mín. e máx., Quartos mín., Vagas mín. e Observações, e clique em Salvar. Depois clique em Recalcular matches para atualizar a lista Imóveis compatíveis, ordenada pela compatibilidade com o perfil do lead.$kb$, $kb$backend-leads$kb$, ARRAY[$kb$como achar imóveis pro perfil do lead$kb$,$kb$como cadastrar o que o cliente procura$kb$,$kb$tem match de imóvel com lead$kb$,$kb$como ver imóveis compatíveis com o cliente$kb$,$kb$onde coloco as preferências do lead$kb$,$kb$como recalcular os matches$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como usar a Captação Automática de leads$kb$, $kb$Acesse Imobiliário › Captação Automática (/app/leads/captacao). Disponível só nos planos Pro e Business. Nos outros planos aparece o botão Ver planos. É um robô que varre a Chaves na Mão em ciclos e coloca os leads novos direto no seu funil. Clique em Nova busca e preencha Nome da busca, Cidade, UF (obrigatórios), Bairro (opcional), Tipo, Finalidade (Venda ou Aluguel), Preço mínimo e máximo e o Ciclo de execução (a cada 8 horas, a cada 12 horas, diariamente ou a cada 2 dias). Depois clique em Criar busca. Cada busca pode ser pausada pela chave ou excluída pela lixeira, e o botão Sincronizar agora roda as buscas ativas na hora.$kb$, $kb$backend-leads$kb$, ARRAY[$kb$como funciona a captação automática$kb$,$kb$como captar leads automaticamente$kb$,$kb$robô de captação de imóveis$kb$,$kb$como criar busca de captação$kb$,$kb$captação automática está bloqueada$kb$,$kb$qual plano tem captação automática$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como transformar um anúncio do Facebook Marketplace em lead$kb$, $kb$Em Imobiliário › Captação Automática (/app/leads/captacao), planos Pro e Business, vá até Importação manual (Facebook Marketplace) e clique em Importar anúncio. O Marketplace não permite robôs, então abra o anúncio com o seu login e cole o Link do anúncio (obrigatório). Se quiser, cole também o texto do anúncio, e os campos são preenchidos automaticamente. Confira Título (obrigatório), Preço, Cidade/bairro, Descrição, Nome do contato e Telefone e clique em Criar lead a partir do anúncio. Se o anúncio já tiver sido importado antes, nenhum lead duplicado é criado.$kb$, $kb$backend-leads$kb$, ARRAY[$kb$como importar anúncio do marketplace$kb$,$kb$como pegar lead do facebook marketplace$kb$,$kb$dá pra captar do marketplace$kb$,$kb$como criar lead de anúncio do facebook$kb$,$kb$importar anúncio de proprietário$kb$,$kb$marketplace vira lead?$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como fazer a análise de risco de um proponente pelo CPF$kb$, $kb$Acesse Imobiliário › Análise de Risco (/app/leads/analise-risco). Digite o CPF do proponente (o sistema valida o número). Se quiser, escolha um lead em Vincular a um lead (opcional) e clique em Consultar. O resultado mostra o Score de crédito com gráficos e conteúdo para você apresentar ao proprietário do imóvel, e o botão Imprimir gera a versão impressa. Quando há um lead vinculado, a consulta fica registrada na timeline dele. A ficha do lead também tem uma consulta rápida de CPF.$kb$, $kb$backend-leads$kb$, ARRAY[$kb$como consulto o cpf do inquilino$kb$,$kb$como fazer análise de crédito$kb$,$kb$onde fica a análise de risco$kb$,$kb$como ver o score do cliente$kb$,$kb$como imprimir a análise de risco$kb$,$kb$consultar cpf do proponente$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como criar funis e etapas personalizados$kb$, $kb$Acesse Configurações › Funis (/app/configuracoes/funis), na tela Funis de leads. Na coluna Funis, digite o nome em Novo funil (ex.: Locação, Venda, Lançamento) e clique em +. O funil padrão aparece marcado como (padrão). Selecione um funil para editar as etapas: renomeie, defina o SLA (h) de cada uma e marque se a etapa é de Ganho ou Perdido. Para adicionar uma etapa, use o campo Nova etapa. Para apagar um funil, use a lixeira ao lado do nome.$kb$, $kb$backend-leads$kb$, ARRAY[$kb$como crio um funil novo$kb$,$kb$como mudar as etapas do funil$kb$,$kb$dá pra ter funil de locação e de venda$kb$,$kb$como configurar sla da etapa$kb$,$kb$onde edito os funis de leads$kb$,$kb$como adicionar etapa no funil$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como configurar o lead scoring (pontuação de leads)$kb$, $kb$Acesse Configurações › Lead scoring (/app/configuracoes/scoring). Escolha um evento (Lead criado, Lead contatado, Visita marcada, Visita realizada, Proposta enviada, E-mail aberto pelo lead ou Lead respondeu no WhatsApp), informe quantos pontos ele vale e clique em Adicionar. As regras aparecem listadas com a pontuação (ex.: +10), e a lixeira remove uma regra. A ideia é usar a pontuação para priorizar os follow-ups dos leads mais engajados.$kb$, $kb$backend-leads$kb$, ARRAY[$kb$como funciona o lead scoring$kb$,$kb$como dar pontos para os leads$kb$,$kb$como configurar pontuação de lead$kb$,$kb$como priorizar leads quentes$kb$,$kb$onde crio regras de score$kb$,$kb$lead scoring onde fica$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como criar cadências de follow-up$kb$, $kb$Acesse Configurações › Cadências (/app/configuracoes/cadencias), na tela Cadências de follow-up. Digite o nome em Nova cadência e clique em +. Com a cadência selecionada, clique em + Passo para cada contato da sequência. Em cada passo, escolha o canal (WhatsApp, E-mail ou Ligação), quantas horas após o anterior ele deve acontecer, o assunto (opcional) e o texto. Use {{nome}} no texto para personalizar com o nome do lead. A lixeira remove um passo.$kb$, $kb$backend-leads$kb$, ARRAY[$kb$como criar uma cadência$kb$,$kb$como montar sequência de follow-up$kb$,$kb$como programar mensagens para o lead$kb$,$kb$cadência de whatsapp e email$kb$,$kb$como personalizar mensagem com nome do lead$kb$,$kb$onde configuro cadências$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como conversar com interessados pelo chat$kb$, $kb$O chat fica no ícone Chat no topo da tela, ao lado de Planos & Assinatura (no celular, dentro do menu Mais opções), e abre em /app/chat. Ali aparecem as conversas que os interessados iniciam sobre os imóveis. Busque por imóvel ou contato e filtre por Todas, Vendendo ou Comprando. Clique numa conversa para responder: Enter envia e Shift+Enter quebra linha. Dentro da ficha de cada lead (Imobiliário › Leads) também há o bloco Conversa com o lead, onde Ctrl/⌘ + Enter envia a mensagem.$kb$, $kb$backend-leads$kb$, ARRAY[$kb$onde fica o chat$kb$,$kb$como respondo mensagem de cliente$kb$,$kb$como falar com o interessado no imóvel$kb$,$kb$onde vejo as conversas$kb$,$kb$chat com lead$kb$,$kb$como mandar mensagem pelo sistema$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como agendar uma visita$kb$, $kb$Acesse Imobiliário › Agenda de visitas (/app/visitas) e clique em Nova visita. Escolha o Imóvel (obrigatório), o Corretor e o Lead, informe Data e Hora (obrigatórias), a Duração em minutos (padrão 30) e as Observações, e clique em Agendar. A agenda pode ser vista em Lista ou por Mês. Em cada visita, mude o status para Agendada, Confirmada, Realizada ou Cancelada, ou exclua pela lixeira. Na ficha de um lead, o botão Agendar visita abre o Roteiro de Visitas com o lead já preenchido.$kb$, $kb$backend-agenda$kb$, ARRAY[$kb$como agendo uma visita$kb$,$kb$como marcar visita com cliente$kb$,$kb$onde fica a agenda de visitas$kb$,$kb$como confirmar uma visita$kb$,$kb$como cancelar visita$kb$,$kb$como ver as visitas do mês$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como usar o Roteiro de Visitas$kb$, $kb$Acesse Imobiliário › Roteiro de Visitas (/app/roteiro-visitas). É um quadro para acompanhar cada visita do agendamento ao feedback, com as colunas A visitar, Em rota, Realizada, Feedback registrado e Não compareceu/Cancelada, além de Sem etapa. Clique em Nova visita, preencha Imóvel, Data e Hora (obrigatórios), Lead e Observações e clique em Criar. A visita entra na primeira coluna. Arraste os cards entre as colunas e clique num card para escrever o Registro da visita (feedback, impressões, próximos passos) e Salvar. Administradores podem escolher o corretor da visita, filtrar por corretor e usar Gerenciar colunas para renomear, excluir ou criar colunas.$kb$, $kb$backend-agenda$kb$, ARRAY[$kb$como funciona o roteiro de visitas$kb$,$kb$como registrar feedback da visita$kb$,$kb$como acompanhar as visitas do dia$kb$,$kb$como mudar a visita de coluna$kb$,$kb$como criar coluna no roteiro$kb$,$kb$como ver visitas de outro corretor$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como criar e acompanhar tarefas e lembretes$kb$, $kb$Acesse Imobiliário › Minhas tarefas (/app/tarefas) e clique em Nova Tarefa. Escolha o Tipo (Tarefa, Ligação, WhatsApp, E-mail ou Reunião) e a Prioridade (Baixa, Média ou Alta) e, se quiser, um Parceiro comercial, que também pode ser criado na hora com + Criar novo parceiro. Preencha Título (obrigatório), Descrição / observações e Prazo / retorno e clique em Criar. No topo aparecem os contadores Atrasadas, Hoje e Pendentes, e os filtros Minhas pendentes, Todas pendentes e Concluídas. Clique no círculo para concluir, e o ícone de rota gera uma visita a partir da tarefa. Na ficha do lead, o bloco Tarefas e lembretes (botão Nova) cria tarefas já ligadas ao lead.$kb$, $kb$backend-agenda$kb$, ARRAY[$kb$como crio uma tarefa$kb$,$kb$como colocar lembrete de retorno$kb$,$kb$onde vejo minhas tarefas atrasadas$kb$,$kb$como marcar tarefa como concluída$kb$,$kb$como criar follow-up para o lead$kb$,$kb$como transformar tarefa em visita$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como gerenciar parceiros comerciais (construtoras, redes e portais)$kb$, $kb$Acesse Imobiliário › Parceiros Comerciais (/app/parceiros-comerciais). É um quadro com as colunas Novo Contato, Em Conversa, Aguardando Retorno, Parceria Ativa e Sem Interesse. Clique em Novo Parceiro e informe Empresa ou Nome do contato (pelo menos um), Tipo (Construtora, Imobiliária / Rede, Portal ou Outro), Cargo, Telefone, E-mail, Canal usado e Observações, e clique em Adicionar. Arraste os cards conforme a negociação avança. Clique num parceiro para ver Interações e tarefas e usar Registrar nova interação, que aceita prazo. Administradores podem usar Gerenciar colunas.$kb$, $kb$backend-geral$kb$, ARRAY[$kb$como cadastro uma construtora parceira$kb$,$kb$como acompanhar contato com incorporadora$kb$,$kb$onde ficam os parceiros comerciais$kb$,$kb$como registrar interação com parceiro$kb$,$kb$como organizar prospecção de construtoras$kb$,$kb$kanban de parceiros$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como conectar a Página do Facebook e o Instagram$kb$, $kb$Acesse Marketing › Portais & Redes sociais (/app/portais) e clique no card Facebook & Instagram (/app/portais/meta). A conexão usa o seu próprio App da Meta, e a tela tem um passo a passo de uns 10 minutos: Business Manager, criar aplicativo do tipo Negócios, adicionar os produtos, autorizar a Página, configurar o webhook leadgen e a URI de redirecionamento. Cole o ID do aplicativo e a Chave secreta do aplicativo e clique em Salvar. Se a Página pertence a um Portfólio Empresarial, salve também o ID de Configuração de Login. Depois clique em Conectar Facebook. Com isso, os leads das suas campanhas no Facebook e Instagram entram direto no funil e você pode publicar imóveis nas redes. Para desfazer, use Desconectar Página.$kb$, $kb$backend-marketing$kb$, ARRAY[$kb$como conecto meu facebook$kb$,$kb$como integrar o instagram$kb$,$kb$como receber leads do facebook no sistema$kb$,$kb$onde coloco o id do aplicativo da meta$kb$,$kb$erro nenhuma página do facebook encontrada$kb$,$kb$como desconectar a página do facebook$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como publicar um imóvel no Facebook e Instagram$kb$, $kb$Primeiro conecte sua Página em Marketing › Portais & Redes sociais › Facebook & Instagram. O imóvel precisa estar publicado e com status Ativo. Abra o imóvel em Imobiliário › Publicar Imóveis e vá até Publicar nas redes sociais. Escolha a Rede (Facebook, Instagram ou Ambas, sendo que as duas últimas exigem Instagram vinculado), o Tipo de post (Post (feed) ou Story), o Tamanho, a Foto e o Modelo. Em posts, marque Incluir todas as fotos do imóvel (carrossel) para enviar as demais fotos junto. Escreva a Legenda ou clique em Gerar com IA, depois em Gerar prévia, e por fim em Publicar.$kb$, $kb$backend-marketing$kb$, ARRAY[$kb$como posto o imóvel no instagram$kb$,$kb$como publicar no facebook direto do sistema$kb$,$kb$como fazer story do imóvel$kb$,$kb$como postar carrossel de fotos$kb$,$kb$não aparece a opção de publicar nas redes$kb$,$kb$como gerar legenda com ia para o post$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como conectar o Canva e editar a arte do post$kb$, $kb$Acesse Marketing › Portais & Redes sociais (/app/portais) e clique no card Canva (/app/portais/canva). Siga o passo a passo da tela: crie uma integração Privada na Canva, configure o Redirect URI, as permissões (asset:read, asset:write, design:content:read e design:content:write) e a navegação de retorno. Cole o Client ID e o Client Secret, salve e clique em Conectar Canva. Depois, na seção Publicar nas redes sociais do imóvel, gere a prévia e clique em Editar no Canva. Ao terminar a edição, você volta automaticamente para o imob365 com a imagem editada, pronta para publicar.$kb$, $kb$backend-marketing$kb$, ARRAY[$kb$como integrar o canva$kb$,$kb$como editar o post no canva$kb$,$kb$onde coloco client id do canva$kb$,$kb$editar no canva não aparece$kb$,$kb$como personalizar a arte do imóvel$kb$,$kb$como desconectar o canva$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como criar uma campanha no Google Ads$kb$, $kb$Acesse Marketing › Google Ads (/app/marketing/google-ads). Em Nova campanha, preencha Nome da campanha, Palavras-chave, Tipo de anúncio (Rede de Pesquisa, Rede de Display, Vídeo ou Shopping), Orçamento do período (R$) e Duração (dias) e clique em Calcular e criar campanha. O sistema mostra o investimento total. Em Minhas campanhas, clique em Pagar e enviar pra ativação. A ativação é feita pela equipe imob365 depois da confirmação do pagamento. Os status possíveis são Rascunho, Aguardando pagamento, Em análise, Ativa, Pausada, Encerrada ou Rejeitada (com o motivo). Com a campanha Ativa, clique em Ver performance para ver Impressões, Cliques, Custo e Conversões.$kb$, $kb$backend-marketing$kb$, ARRAY[$kb$como anuncio no google$kb$,$kb$como criar campanha google ads$kb$,$kb$quanto custa anunciar no google$kb$,$kb$como pagar a campanha do google$kb$,$kb$como ver resultado da campanha$kb$,$kb$minha campanha foi rejeitada$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como gerar um QR Code para placas e materiais$kb$, $kb$Acesse Site › Gerador de QR Code (/app/qr-code). Escolha para onde o QR Code leva: Link da internet (qualquer URL), Publicação deste site (Imóvel, Empreendimento ou Artigo do blog já publicado), Ligação telefônica ou WhatsApp (número com DDD e mensagem inicial). Se quiser, dê um Nome interno deste QR Code e clique em Gerar QR Code. Baixe a imagem em Baixar PNG ou copie o link. Na lista QR Codes já gerados, cada QR mostra quantas leituras teve.$kb$, $kb$backend-marketing$kb$, ARRAY[$kb$como faço um qr code$kb$,$kb$como criar qr code pra placa$kb$,$kb$qr code que abre o whatsapp$kb$,$kb$qr code do imóvel$kb$,$kb$como saber quantas pessoas escanearam$kb$,$kb$como baixar o qr code$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como criar e compartilhar o Cartão Virtual do corretor$kb$, $kb$Acesse Imobiliário › Cartão Virtual (/app/cartao-virtual). Se ainda não tiver um, clique em Criar meu Cartão Virtual, confira Nome completo (obrigatório), E-mail e Telefone e clique em Criar Cartão Virtual. Depois preencha Contato (Telefone, WhatsApp…) e Redes sociais (Instagram, Facebook, LinkedIn, site) e clique em Salvar. Em Compartilhar, use Ver cartão público, Copiar link, Baixar QR Code ou Baixar contato (.vcf). Também dá para enviar o CIRP (carteira do CRECI), em foto ou PDF até 10MB, que fica visível só para você e para a administração. Administradores podem escolher outro membro da equipe em Selecionar cartão.$kb$, $kb$backend-marketing$kb$, ARRAY[$kb$como crio meu cartão virtual$kb$,$kb$cartão de visita digital$kb$,$kb$como compartilhar meu cartão$kb$,$kb$como baixar meu contato vcf$kb$,$kb$onde envio minha carteira do creci$kb$,$kb$como criar cartão para outro corretor$kb$,$kb$como fazer meu cartão virtual$kb$,$kb$onde baixo o qr code do meu cartão$kb$,$kb$como compartilhar meu cartão de visita digital$kb$,$kb$como gerar vcard$kb$,$kb$link do cartão virtual$kb$,$kb$como editar redes sociais no cartão$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como fazer parcerias com outras imobiliárias$kb$, $kb$Acesse Marketing › Parcerias (/app/parcerias). Ative Participar da rede de parceiros para aparecer na busca de outras imobiliárias. Em Como dividir a comissão, defina os percentuais de Quem cadastrou o imóvel e Quem trouxe o cliente (padrão 50/50, a soma tem que dar 100%) e clique em Salvar. Busque pelo nome da imobiliária (mínimo 2 letras) e clique em Solicitar. Os pedidos que você recebe aparecem em Pedidos recebidos, com Aceitar e Recusar, e os pedidos enviados podem ser cancelados. Todo imóvel publicado e ativo fica automaticamente visível para as parceiras conectadas.$kb$, $kb$backend-marketing$kb$, ARRAY[$kb$como faço parceria com outra imobiliária$kb$,$kb$como compartilhar imóveis com parceiros$kb$,$kb$como dividir comissão em parceria$kb$,$kb$como aceitar pedido de parceria$kb$,$kb$rede de parceiros como funciona$kb$,$kb$como achar imobiliárias parceiras$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como escrever e publicar artigos no blog do site$kb$, $kb$Acesse Site › Blog & Artigos (/app/site/blog) e clique em Novo Artigo. Na aba 1. Conteúdo Principal, preencha Título do Artigo (obrigatório), URL Slug, Categoria, URL da Imagem de Capa, Breve Resumo e o Texto completo do artigo. Na aba 2. Configurações de SEO (Google), defina Título SEO, Meta Description e Palavras-chave. Em Status & Publicação, escolha Rascunho ou Publicar No Ar e clique em Cadastrar Artigo (ou Atualizar Artigo, quando for edição). Os artigos aparecem só para os visitantes do site da sua imobiliária, e a lista pode ser filtrada por Todos, Ativos/Publicados e Rascunhos.$kb$, $kb$backend-site$kb$, ARRAY[$kb$como escrevo um post no blog$kb$,$kb$como publicar artigo no meu site$kb$,$kb$como deixar artigo em rascunho$kb$,$kb$como configurar seo do artigo$kb$,$kb$como editar um artigo do blog$kb$,$kb$onde fica o blog da imobiliária$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como ver a prévia do site da imobiliária$kb$, $kb$Acesse Site › Prévia do Site (/app/site/previa) para ver como está a home pública da sua imobiliária agora. Alterne entre Desktop e Mobile para conferir nos dois formatos. O selo no topo mostra se o site está Publicado ou em Rascunho, e o botão Ver em nova aba abre o site real. Se o site ainda não foi configurado, a tela indica o caminho Site › Site da imobiliária. O botão Assistente de Configuração ajuda a refazer o site ou revisar tudo passo a passo.$kb$, $kb$backend-site$kb$, ARRAY[$kb$como vejo como ficou meu site$kb$,$kb$como ver o site no celular$kb$,$kb$prévia do site$kb$,$kb$meu site está publicado?$kb$,$kb$como abrir meu site$kb$,$kb$como testar o site antes de publicar$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como usar o assistente de configuração do site$kb$, $kb$Acesse /app/site/assistente ou clique em Assistente de Configuração em Site › Prévia do Site. O assistente guia a criação do site nas etapas Boas-vindas, Estilo do site, Logo, Cores, Título, Sobre você, Contato, Páginas, Seções e SEO avançado. O estilo pode ser trocado depois a qualquer momento. Ao final, clique em Publicar meu site para colocar o site no ar. Também é possível salvar como rascunho e voltar depois.$kb$, $kb$backend-site$kb$, ARRAY[$kb$como crio meu site rápido$kb$,$kb$tem assistente pra montar o site$kb$,$kb$como escolher o estilo do site$kb$,$kb$como publicar meu site$kb$,$kb$como refazer o site do zero$kb$,$kb$passo a passo do site$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
  perguntas = EXCLUDED.perguntas, ativo = true, updated_at = now();
INSERT INTO public.ai_knowledge_base (titulo, conteudo, categoria, perguntas, ativo)
VALUES ($kb$Como adicionar widgets nas barras laterais do site$kb$, $kb$Acesse Site › Widgets de Conteúdo (/app/site/widgets-conteudo) e clique em + Adicionar widget. Escolha o tipo: Imóveis recentes, Posts do blog, Contato rápido, Redes sociais, Banner publicitário (imagem até 2MB e link) ou Texto livre. Em Onde aparece, escolha Barra esquerda ou Barra direita, configure o conteúdo e clique em Salvar widget. Nas colunas Barra lateral esquerda e Barra lateral direita, dá para editar, ativar ou desativar, mudar a ordem e remover cada widget. Os widgets de contato e redes sociais usam os dados já cadastrados em Site › Site da imobiliária.$kb$, $kb$backend-site$kb$, ARRAY[$kb$como coloco um banner no site$kb$,$kb$como adicionar widget na lateral$kb$,$kb$como mostrar imóveis recentes na lateral$kb$,$kb$como colocar posts do blog na barra lateral$kb$,$kb$como colocar aviso no site$kb$,$kb$widgets do site onde configura$kb$]::text[], true)
ON CONFLICT (titulo) DO UPDATE SET conteudo = EXCLUDED.conteudo, categoria = EXCLUDED.categoria,
